--
-- Name: add_user_to_team_workspaces(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_user_to_team_workspaces() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- When a user joins a team, add them to every existing workspace of that team.
  INSERT INTO workspace_members (workspace_id, user_id, role)
  SELECT w.id, NEW.user_id,
    CASE WHEN NEW.role IN ('founder', 'owner', 'admin') THEN 'admin'::workspace_role
         WHEN NEW.role = 'member' THEN 'member'::workspace_role
         ELSE 'viewer'::workspace_role END
  FROM workspaces w
  WHERE w.team_id = NEW.team_id
    AND NOT EXISTS (SELECT 1 FROM workspace_members wm
                    WHERE wm.workspace_id = w.id AND wm.user_id = NEW.user_id);
  RETURN NEW;
END; $$;


--
-- Name: agent_routine_runs_stamp_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_routine_runs_stamp_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.version IS NULL AND NEW.routine_id IS NOT NULL THEN
    SELECT r.version INTO NEW.version FROM public.agent_routines r WHERE r.id = NEW.routine_id;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: agent_routine_snapshot(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_routine_snapshot(r jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT coalesce(jsonb_object_agg(k, r -> k), '{}'::jsonb)
  FROM unnest(ARRAY[
    'name', 'prompt', 'trigger_kind', 'frequency', 'at_time', 'day_of_week', 'day_of_month',
    'timezone', 'offset_minutes', 'entity_id', 'condition', 'action', 'artifact',
    'destination', 'destination_target', 'tools', 'steps', 'trigger_config'
  ]) AS k
  WHERE r ? k
$$;


--
-- Name: agent_routines_version_bump(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_routines_version_bump() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.version := coalesce(NEW.version, 1);
  ELSIF public.agent_routine_snapshot(to_jsonb(NEW)) IS DISTINCT FROM public.agent_routine_snapshot(to_jsonb(OLD)) THEN
    NEW.version := coalesce(OLD.version, 0) + 1;
  ELSE
    NEW.version := OLD.version;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: agent_routines_version_keep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_routines_version_keep() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.version IS DISTINCT FROM OLD.version THEN
    INSERT INTO public.automation_versions (workspace_id, routine_id, version, snapshot, published_by)
    VALUES (NEW.workspace_id, NEW.id, NEW.version, public.agent_routine_snapshot(to_jsonb(NEW)), NEW.edited_by)
    ON CONFLICT (routine_id, version) DO NOTHING;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: api_request_log_activity(uuid, timestamp with time zone, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_request_log_activity(p_workspace_id uuid, p_since timestamp with time zone, p_bucket text DEFAULT 'day'::text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  with r as (
    select surface, route, target, status, latency_ms, client, api_key_id, at
      from public.api_request_log
     where workspace_id = p_workspace_id
       and at >= p_since
  ),
  lim as (select greatest(1, least(coalesce(p_limit, 10), 100)) as n)
  select jsonb_build_object(
    'totals', (
      select jsonb_build_object(
        'calls',    count(*),
        'mcp',      count(*) filter (where surface = 'mcp'),
        'rest',     count(*) filter (where surface = 'rest'),
        'errors',   count(*) filter (where status >= 400),
        'p50_ms',   percentile_disc(0.5)  within group (order by latency_ms),
        'p95_ms',   percentile_disc(0.95) within group (order by latency_ms),
        'keys',     count(distinct api_key_id),
        'clients',  count(distinct client),
        'targets',  count(distinct target)
      ) from r
    ),
    'series', coalesce((
      select jsonb_agg(jsonb_build_object(
               'bucket', s.bucket, 'calls', s.calls, 'mcp', s.mcp, 'rest', s.rest, 'errors', s.errors
             ) order by s.bucket)
        from (
          select case when p_bucket = 'hour'
                      then to_char(date_trunc('hour', at at time zone 'UTC'), 'YYYY-MM-DD"T"HH24":00:00Z"')
                      else to_char((at at time zone 'UTC')::date, 'YYYY-MM-DD') end as bucket,
                 count(*)                                  as calls,
                 count(*) filter (where surface = 'mcp')   as mcp,
                 count(*) filter (where surface = 'rest')  as rest,
                 count(*) filter (where status >= 400)     as errors
            from r group by 1
        ) s
    ), '[]'::jsonb),
    'by_route', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.calls desc, x.route)
        from (
          select surface, route, count(*) as calls,
                 count(*) filter (where status >= 400) as errors,
                 percentile_disc(0.95) within group (order by latency_ms) as p95_ms,
                 max(at) as last_at
            from r group by surface, route
           order by calls desc, route
           limit (select n from lim)
        ) x
    ), '[]'::jsonb),
    'by_target', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.calls desc, x.target)
        from (
          select target, count(*) as calls,
                 count(*) filter (where status >= 400) as errors,
                 max(at) as last_at
            from r where target is not null group by target
           order by calls desc, target
           limit (select n from lim)
        ) x
    ), '[]'::jsonb),
    'by_key', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.calls desc)
        from (
          select api_key_id, count(*) as calls,
                 count(*) filter (where status >= 400) as errors,
                 max(at) as last_at
            from r group by api_key_id
        ) x
    ), '[]'::jsonb),
    'by_client', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.calls desc, x.client)
        from (
          select coalesce(client, '') as client, count(*) as calls,
                 count(*) filter (where status >= 400) as errors,
                 max(at) as last_at
            from r group by 1
           order by calls desc, client
           limit (select n from lim)
        ) x
    ), '[]'::jsonb)
  );
$$;


--
-- Name: FUNCTION api_request_log_activity(p_workspace_id uuid, p_since timestamp with time zone, p_bucket text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.api_request_log_activity(p_workspace_id uuid, p_since timestamp with time zone, p_bucket text, p_limit integer) IS 'Settings > API & MCP activity (GET-898): totals, series, top routes/targets/clients and per-key counts for one workspace since p_since.';


--
-- Name: api_request_log_by_key(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_request_log_by_key(p_workspace_id uuid, p_since timestamp with time zone) RETURNS TABLE(api_key_id uuid, calls bigint, credits bigint)
    LANGUAGE sql STABLE
    AS $$
  select api_key_id, count(*) as calls, coalesce(sum(credits), 0)::bigint as credits
    from public.api_request_log
   where workspace_id = p_workspace_id
     and at >= p_since
   group by api_key_id
   order by calls desc;
$$;


--
-- Name: api_request_log_by_route(uuid, uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_request_log_by_route(p_workspace_id uuid, p_api_key_id uuid, p_since timestamp with time zone, p_limit integer DEFAULT 10) RETURNS TABLE(route text, surface text, calls bigint)
    LANGUAGE sql STABLE
    AS $$
  select route, surface, count(*) as calls
    from public.api_request_log
   where workspace_id = p_workspace_id
     and api_key_id   = p_api_key_id
     and at >= p_since
   group by route, surface
   order by calls desc, route
   limit greatest(1, least(p_limit, 100));
$$;


--
-- Name: api_request_log_per_day(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_request_log_per_day(p_workspace_id uuid, p_api_key_id uuid, p_since timestamp with time zone) RETURNS TABLE(day date, calls bigint, errors bigint)
    LANGUAGE sql STABLE
    AS $$
  select (at at time zone 'UTC')::date as day,
         count(*)                                as calls,
         count(*) filter (where status >= 400)   as errors
    from public.api_request_log
   where workspace_id = p_workspace_id
     and api_key_id   = p_api_key_id
     and at >= p_since
   group by 1
   order by 1;
$$;


--
-- Name: attribute_relationship(uuid, uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attribute_relationship(p_workspace uuid, p_entity uuid, p_user uuid, p_at timestamp with time zone, p_label text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_val        jsonb;
  v_members    jsonb := '[]'::jsonb;
  v_new        jsonb := '[]'::jsonb;
  v_elem       jsonb;
  v_found      boolean := false;
  v_assigned   jsonb;
  v_primary    text;
  v_best_touch text;
  v_touch      text;
  -- Match JavaScript's Date.toISOString(): millisecond precision, trailing 'Z'.
  v_at_text    text := to_char(p_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
BEGIN
  IF p_user IS NULL THEN RETURN; END IF;

  -- Serialise concurrent attributions to THIS account's relationship claim.
  -- Scoped to the exact (workspace, entity); released at transaction end.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(p_workspace::text || ':' || p_entity::text || ':relationship_owner', 0));

  SELECT value INTO v_val
    FROM public.claims
   WHERE workspace_id = p_workspace
     AND entity_id    = p_entity
     AND property     = 'relationship_owner'
     AND invalid_at IS NULL;

  v_members  := COALESCE(v_val->'members', '[]'::jsonb);
  v_assigned := v_val->'assigned';

  -- Rebuild members, bumping the caller's row in place if it already exists.
  FOR v_elem IN SELECT * FROM jsonb_array_elements(v_members) LOOP
    IF (v_elem->>'user_id') = p_user::text THEN
      v_found := true;
      v_touch := v_elem->>'last_touch';
      IF v_touch IS NULL OR v_at_text > v_touch THEN v_touch := v_at_text; END IF;
      v_elem := jsonb_build_object(
        'user_id',    p_user::text,
        'label',      CASE WHEN p_label IS NOT NULL THEN to_jsonb(p_label)
                           ELSE COALESCE(v_elem->'label', 'null'::jsonb) END,
        'last_touch', v_touch,
        'touches',    COALESCE((v_elem->>'touches')::int, 0) + 1
      );
    END IF;
    v_new := v_new || v_elem;
  END LOOP;

  IF NOT v_found THEN
    v_new := v_new || jsonb_build_object(
      'user_id',    p_user::text,
      'label',      to_jsonb(p_label),   -- JSON null when no label, matching the TS path
      'last_touch', v_at_text,
      'touches',    1
    );
  END IF;

  -- primary = most recent toucher; strict '>' keeps the earlier member on a tie,
  -- matching the TS reduce().
  v_best_touch := NULL;
  FOR v_elem IN SELECT * FROM jsonb_array_elements(v_new) LOOP
    v_touch := COALESCE(v_elem->>'last_touch', '');
    IF v_best_touch IS NULL OR v_touch > v_best_touch THEN
      v_best_touch := v_touch;
      v_primary    := v_elem->>'user_id';
    END IF;
  END LOOP;

  v_val := jsonb_build_object('primary', v_primary, 'members', v_new);
  IF v_assigned IS NOT NULL AND v_assigned <> 'null'::jsonb THEN
    v_val := v_val || jsonb_build_object('assigned', v_assigned);
  END IF;

  -- Upsert the asserted claim (one row per (workspace, entity, property)).
  INSERT INTO public.claims (
    workspace_id, entity_id, property, value, distribution, confidence,
    epistemic_class, freshness, valid_from, invalid_at,
    supporting_observation_ids, observation_count, last_observed_at, computed_at
  ) VALUES (
    p_workspace, p_entity, 'relationship_owner', v_val, NULL, 1.0,
    'asserted', 'fresh', now(), NULL,
    '{}'::uuid[], 0, NULL, now()
  )
  ON CONFLICT (workspace_id, entity_id, property) DO UPDATE
    SET value           = EXCLUDED.value,
        epistemic_class = 'asserted',
        confidence      = 1.0,
        freshness       = 'fresh',
        invalid_at      = NULL,
        computed_at     = now();

  -- Provenance: the first time a member is attributed they GAINED access. Written
  -- in-transaction so the grant and the access can never diverge.
  IF NOT v_found THEN
    INSERT INTO public.audit_log (action, actor_user_id, target_type, target_id, target_workspace_id, metadata)
    VALUES ('access.granted', NULL, 'account', p_entity::text, p_workspace,
            jsonb_build_object('member_user_id', p_user::text, 'via', 'co-attendance',
                               'label', to_jsonb(p_label)));
  END IF;
END;
$$;


