-- Name: find_entities_by_phone(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_entities_by_phone(p_workspace_id uuid, p_phone_key text) RETURNS TABLE(entity_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT c.entity_id
    FROM public.claims c
   WHERE c.workspace_id = p_workspace_id
     AND c.property = 'phone'
     AND c.invalid_at IS NULL
     AND length(p_phone_key) = 10
     AND right(regexp_replace(c.value #>> '{}', '\D', '', 'g'), 10) = p_phone_key
   LIMIT 50;
$$;


--
-- Name: generate_referral_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_referral_code(user_name text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql
    AS $$
  DECLARE
    base_code TEXT;
    final_code TEXT;
    counter INTEGER := 0;
  BEGIN
    IF user_name IS NOT NULL AND LENGTH(TRIM(user_name)) > 0 THEN
      base_code := UPPER(LEFT(REGEXP_REPLACE(user_name, '[^a-zA-Z0-9]', '', 'g'), 6));
      IF LENGTH(base_code) < 3 THEN
        base_code := 'REF';
      END IF;
    ELSE
      base_code := 'REF';
    END IF;

    LOOP
      final_code := base_code || LPAD(FLOOR(RANDOM() * 10000)::TEXT, 4, '0');
      IF NOT EXISTS (SELECT 1 FROM affiliate_partners WHERE referral_code = final_code) THEN
        RETURN final_code;
      END IF;
      counter := counter + 1;
      IF counter > 100 THEN
        final_code := 'REF' || gen_random_uuid()::TEXT;
        final_code := UPPER(LEFT(REPLACE(final_code, '-', ''), 10));
        RETURN final_code;
      END IF;
    END LOOP;
  END;
  $$;


