--
-- Name: claims; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.claims (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    entity_id uuid NOT NULL,
    property text NOT NULL,
    value jsonb NOT NULL,
    distribution jsonb,
    confidence real NOT NULL,
    epistemic_class text NOT NULL,
    freshness text DEFAULT 'fresh'::text NOT NULL,
    decays_at timestamp with time zone,
    supporting_observation_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    observation_count integer DEFAULT 0 NOT NULL,
    last_observed_at timestamp with time zone,
    embedding public.vector(1536),
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    valid_from timestamp with time zone,
    invalid_at timestamp with time zone,
    derived_visibility text,
    CONSTRAINT claims_derived_visibility_check CHECK (((derived_visibility IS NULL) OR (derived_visibility = ANY (ARRAY['inherit'::text, 'shared'::text])))),
    CONSTRAINT claims_epistemic_class_check CHECK ((epistemic_class = ANY (ARRAY['observed'::text, 'inferred'::text, 'predicted'::text, 'asserted'::text]))),
    CONSTRAINT claims_freshness_check CHECK ((freshness = ANY (ARRAY['fresh'::text, 'aging'::text, 'suspect'::text, 'expired'::text])))
)
WITH (autovacuum_analyze_scale_factor='0.02', autovacuum_vacuum_scale_factor='0.05');


--
-- Name: COLUMN claims.derived_visibility; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.claims.derived_visibility IS 'null/inherit = visible per the account dial (default). shared = admin-promoted, readable workspace-wide without exposing the supporting raw.';


