--
-- Name: observations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.observations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    entity_id uuid NOT NULL,
    kind text NOT NULL,
    property text NOT NULL,
    value jsonb NOT NULL,
    source text NOT NULL,
    method text NOT NULL,
    source_confidence real,
    observed_at timestamp with time zone NOT NULL,
    ingested_at timestamp with time zone DEFAULT now() NOT NULL,
    external_id text,
    raw jsonb,
    content_hash text,
    embedding public.vector(1536),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    owner_user_id uuid,
    source_ref text,
    CONSTRAINT observations_kind_check CHECK ((kind = ANY (ARRAY['state'::text, 'event'::text])))
)
WITH (autovacuum_analyze_scale_factor='0.02', autovacuum_vacuum_scale_factor='0.05');


--
-- Name: COLUMN observations.content_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.observations.content_hash IS 'sha256 of the stored raw payload — lets a resolved raw be verified untampered.';


--
-- Name: COLUMN observations.owner_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.observations.owner_user_id IS 'The rep this raw row came through; scopes its body to that rep + in-touch members (PRIVACY_MODEL.md). A durable scope token, deliberately WITHOUT an ON DELETE SET NULL FK: it must survive user deletion so a departed rep''s content stays private rather than becoming workspace-shared. NULL still means system/derived/shared.';


--
-- Name: COLUMN observations.source_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.observations.source_ref IS 'Verifiable pointer to the raw source (source://<source>/<external_id>, vault path, or git sha). Followed by resolveRaw().';


--
-- Name: leads; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.leads WITH (security_invoker='on') AS
 SELECT e.id,
    ce.collection_id AS lead_list_id,
    e.workspace_id,
    ( SELECT entity_identifiers.value
           FROM public.entity_identifiers
          WHERE ((entity_identifiers.entity_id = e.id) AND (entity_identifiers.kind = 'email'::text) AND (entity_identifiers.status = 'active'::text))
         LIMIT 1) AS email,
    TRIM(BOTH ' '::text FROM concat(COALESCE(( SELECT (claims.value #>> '{}'::text[])
           FROM public.claims
          WHERE ((claims.entity_id = e.id) AND (claims.property = 'first_name'::text) AND (claims.invalid_at IS NULL))
         LIMIT 1), ''::text), ' ', COALESCE(( SELECT (claims.value #>> '{}'::text[])
           FROM public.claims
          WHERE ((claims.entity_id = e.id) AND (claims.property = 'last_name'::text) AND (claims.invalid_at IS NULL))
         LIMIT 1), ''::text))) AS name,
    ( SELECT (claims.value #>> '{}'::text[])
           FROM public.claims
          WHERE ((claims.entity_id = e.id) AND (claims.property = 'company'::text) AND (claims.invalid_at IS NULL))
         LIMIT 1) AS company,
    ( SELECT entity_identifiers.value
           FROM public.entity_identifiers
          WHERE ((entity_identifiers.entity_id = e.id) AND (entity_identifiers.kind = 'linkedin_url'::text) AND (entity_identifiers.status = 'active'::text))
         LIMIT 1) AS linkedin_url,
    ( SELECT min(observations.observed_at) AS min
           FROM public.observations
          WHERE ((observations.entity_id = e.id) AND (observations.property = 'interaction.email_sent'::text))) AS sent_at,
    ( SELECT (claims.value #>> '{}'::text[])
           FROM public.claims
          WHERE ((claims.entity_id = e.id) AND (claims.property = 'send_variant'::text) AND (claims.invalid_at IS NULL))
         LIMIT 1) AS send_variant,
    COALESCE((( SELECT (claims.value #>> '{}'::text[])
           FROM public.claims
          WHERE ((claims.entity_id = e.id) AND (claims.property = 'is_repeat_contact'::text) AND (claims.invalid_at IS NULL))
         LIMIT 1))::boolean, false) AS is_repeat_contact,
    COALESCE(( SELECT claims.value
           FROM public.claims
          WHERE ((claims.entity_id = e.id) AND (claims.property = 'features'::text) AND (claims.invalid_at IS NULL))
         LIMIT 1), '{}'::jsonb) AS features,
    COALESCE(( SELECT claims.value
           FROM public.claims
          WHERE ((claims.entity_id = e.id) AND (claims.property = 'fields'::text) AND (claims.invalid_at IS NULL))
         LIMIT 1), '{}'::jsonb) AS fields,
    (( SELECT (claims.value #>> '{}'::text[])
           FROM public.claims
          WHERE ((claims.entity_id = e.id) AND (claims.property = 'scorecard_score'::text) AND (claims.invalid_at IS NULL))
         LIMIT 1))::integer AS scorecard_score,
    ( SELECT (claims.value #>> '{}'::text[])
           FROM public.claims
          WHERE ((claims.entity_id = e.id) AND (claims.property = 'sentiment'::text) AND (claims.invalid_at IS NULL))
         LIMIT 1) AS reply_outcome,
    ( SELECT max(observations.observed_at) AS max
           FROM public.observations
          WHERE ((observations.entity_id = e.id) AND (observations.property = ANY (ARRAY['interaction.reply'::text, 'interaction.positive_reply'::text, 'interaction.negative_reply'::text, 'interaction.linkedin_reply'::text])))) AS replied_at,
    COALESCE(
        CASE
            WHEN (( SELECT (claims.value #>> '{}'::text[])
               FROM public.claims
              WHERE ((claims.entity_id = e.id) AND (claims.property = 'reachability_status'::text) AND (claims.invalid_at IS NULL))
             LIMIT 1) = 'bounced'::text) THEN 'bounced'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.observations
              WHERE ((observations.entity_id = e.id) AND (observations.property = ANY (ARRAY['interaction.reply'::text, 'interaction.positive_reply'::text, 'interaction.negative_reply'::text, 'interaction.linkedin_reply'::text]))))) THEN 'replied'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.observations
              WHERE ((observations.entity_id = e.id) AND (observations.property = 'interaction.email_sent'::text)))) THEN 'sent'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.observations
              WHERE ((observations.entity_id = e.id) AND (observations.property = 'interaction.linkedin_message_sent'::text)))) THEN 'messaged'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.observations
              WHERE ((observations.entity_id = e.id) AND (observations.property = 'interaction.linkedin_connected'::text)))) THEN 'connected'::text
            ELSE 'pending'::text
        END, 'pending'::text) AS status,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM public.observations
              WHERE (observations.entity_id = e.id)
             LIMIT 1)) THEN e.id
            ELSE NULL::uuid
        END AS contact_id,
    ce.added_at AS created_at,
    COALESCE(( SELECT max(claims.computed_at) AS max
           FROM public.claims
          WHERE (claims.entity_id = e.id)), ce.added_at) AS updated_at,
    ( SELECT (claims.value #>> '{}'::text[])
           FROM public.claims
          WHERE ((claims.entity_id = e.id) AND (claims.property = 'domain'::text) AND (claims.invalid_at IS NULL))
         LIMIT 1) AS domain,
    ( SELECT (claims.value #>> '{}'::text[])
           FROM public.claims
          WHERE ((claims.entity_id = e.id) AND (claims.property = 'reachability_status'::text) AND (claims.invalid_at IS NULL))
         LIMIT 1) AS email_status,
    ( SELECT observations.source
           FROM public.observations
          WHERE ((observations.entity_id = e.id) AND (observations.kind = 'event'::text) AND (observations.property ~~ 'interaction.%'::text) AND (observations.property <> 'interaction.enrichment_run'::text) AND (observations.source <> ALL (ARRAY['prospeo'::text, 'apollo'::text])))
          ORDER BY observations.observed_at DESC
         LIMIT 1) AS last_channel,
    ce.source
   FROM ((public.entities e
     JOIN public.collection_entities ce ON ((ce.entity_id = e.id)))
     JOIN public.collections c ON (((c.id = ce.collection_id) AND (c.kind = 'list'::text))))
  WHERE ((e.type = 'person'::text) AND (e.status = 'active'::text));


--
-- Name: lead_list_leads(uuid, uuid, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_list_leads(p_ws uuid, p_list uuid, p_lim integer DEFAULT 50, p_off integer DEFAULT 0, p_icp text DEFAULT NULL::text, p_sort text DEFAULT 'recent'::text) RETURNS SETOF public.leads
    LANGUAGE sql STABLE
    AS $$
  SELECT l.* FROM leads l
  LEFT JOIN LATERAL (
    SELECT (p.predicted_value->>'score')::numeric AS score
    FROM predictions p
    WHERE p.workspace_id = p_ws AND p.entity_id = l.id AND p.kind = 'icp_fit'
    ORDER BY p.predicted_at DESC
    LIMIT 1
  ) pred ON TRUE
  WHERE l.workspace_id = p_ws AND l.lead_list_id = p_list
    AND (p_icp IS NULL OR (l.fields->>'icp') = p_icp)
  ORDER BY
    CASE WHEN p_sort = 'icp_score_desc'
      THEN COALESCE(pred.score, (l.fields->>'icp_score')::numeric) END DESC NULLS LAST,
    CASE WHEN p_sort = 'icp_score_asc'
      THEN COALESCE(pred.score, (l.fields->>'icp_score')::numeric) END ASC  NULLS LAST,
    l.created_at DESC
  LIMIT GREATEST(p_lim, 1) OFFSET GREATEST(p_off, 0)
$$;


--
-- Name: lead_lists_delete_handler(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_lists_delete_handler() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  DELETE FROM collection_entities WHERE collection_id = OLD.id;
  DELETE FROM collections WHERE id = OLD.id;
  RETURN OLD;
END;
$$;


--
-- Name: lead_lists_insert_handler(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_lists_insert_handler() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  new_id UUID := COALESCE(NEW.id, gen_random_uuid());
BEGIN
  INSERT INTO collections (id, workspace_id, name, kind, source, metadata, created_at)
  VALUES (new_id, NEW.workspace_id, NEW.name, 'list', NEW.source,
          CASE WHEN NEW.columns IS NULL THEN '{}'::jsonb
               ELSE jsonb_build_object('columns', NEW.columns) END,
          COALESCE(NEW.created_at, now()))
  ON CONFLICT (id) DO NOTHING;
  NEW.id := new_id;
  RETURN NEW;
END;
$$;


--
-- Name: lead_lists_update_handler(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_lists_update_handler() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE collections SET
    name = COALESCE(NEW.name, name),
    source = COALESCE(NEW.source, source),
    metadata = CASE
      WHEN NEW.columns IS NOT NULL THEN jsonb_set(COALESCE(metadata,'{}'::jsonb), '{columns}', NEW.columns, true)
      ELSE metadata
    END
  WHERE id = OLD.id;
  RETURN NEW;
END;
$$;


--
-- Name: leads_delete_handler(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leads_delete_handler() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.lead_list_id IS NOT NULL THEN
    DELETE FROM collection_entities WHERE collection_id = OLD.lead_list_id AND entity_id = OLD.id;
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: leads_insert_handler(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leads_insert_handler() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  new_id UUID := COALESCE(NEW.id, gen_random_uuid());
  ws UUID := NEW.workspace_id;
  fn_part TEXT := NULLIF(trim(split_part(COALESCE(NEW.name,''), ' ', 1)),'');
  ln_part TEXT := NULLIF(trim(substring(COALESCE(NEW.name,'') FROM position(' ' IN COALESCE(NEW.name,'')||' ') + 1)),'');
  e_email TEXT := lower(NULLIF(trim(NEW.email),''));
  e_li    TEXT := NULLIF(trim(NEW.linkedin_url),'');
  e_li_norm TEXT := regexp_replace(regexp_replace(lower(split_part(NULLIF(trim(NEW.linkedin_url),''), '?', 1)), '^https?://(www\.)?', ''), '/+$', '');
  existing_id UUID;
BEGIN
  -- Resolve to an existing entity by a strong identifier so a lead doesn't spawn
  -- a duplicate person. LinkedIn match is normalized (lowercase, drop query, strip
  -- protocol/www, strip trailing slash) so URL-shape differences still merge.
  IF NEW.contact_id IS NOT NULL THEN
    new_id := NEW.contact_id;
  ELSE
    SELECT entity_id INTO existing_id FROM entity_identifiers
     WHERE workspace_id = ws AND status = 'active'
       AND ((e_email IS NOT NULL AND kind = 'email' AND value = e_email)
         OR (e_li_norm IS NOT NULL AND e_li_norm <> '' AND kind = 'linkedin_url'
             AND regexp_replace(regexp_replace(lower(split_part(value, '?', 1)), '^https?://(www\.)?', ''), '/+$', '') = e_li_norm))
     LIMIT 1;
    IF existing_id IS NOT NULL THEN new_id := existing_id; END IF;
  END IF;

  INSERT INTO entities (id, workspace_id, type, status, created_at)
  VALUES (new_id, ws, 'person', 'active', COALESCE(NEW.created_at, now()))
  ON CONFLICT (id) DO NOTHING;

  -- Identifiers
  INSERT INTO entity_identifiers (workspace_id, entity_id, kind, value)
  SELECT ws, new_id, k.kind, k.value FROM (VALUES
    ('email',        e_email),
    ('linkedin_url', e_li)
  ) AS k(kind, value)
  WHERE k.value IS NOT NULL
  ON CONFLICT DO NOTHING;

  -- Initial state observations
  INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
  SELECT ws, new_id, 'state', k.property, k.value, 'lead_list', 'trigger', now() FROM (VALUES
    ('first_name',        to_jsonb(fn_part)),
    ('last_name',         to_jsonb(ln_part)),
    ('company',           to_jsonb(NULLIF(trim(NEW.company),''))),
    ('lead_status',       to_jsonb(NULLIF(trim(NEW.status),''))),
    ('send_variant',      to_jsonb(NULLIF(trim(NEW.send_variant),''))),
    ('scorecard_score',   to_jsonb(NEW.scorecard_score)),
    ('is_repeat_contact', to_jsonb(NEW.is_repeat_contact)),
    ('features',          CASE WHEN NEW.features IS NULL OR NEW.features = '{}'::jsonb THEN NULL ELSE NEW.features END),
    ('fields',            CASE WHEN NEW.fields   IS NULL OR NEW.fields   = '{}'::jsonb THEN NULL ELSE NEW.fields   END),
    ('pipeline_stage',    to_jsonb('cold'::text))
  ) AS k(property, value)
  WHERE k.value IS NOT NULL;

  IF NEW.sent_at IS NOT NULL THEN
    INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
    VALUES (ws, new_id, 'event', 'interaction.email_sent',
            jsonb_build_object('variant', NEW.send_variant),
            'lead_list', 'trigger', NEW.sent_at);
  END IF;
  IF NEW.replied_at IS NOT NULL THEN
    INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
    VALUES (ws, new_id, 'event', 'interaction.reply',
            jsonb_build_object('outcome', NEW.reply_outcome),
            'lead_list', 'trigger', NEW.replied_at);
  END IF;

  IF NEW.lead_list_id IS NOT NULL THEN
    INSERT INTO collection_entities (collection_id, entity_id, added_at, source)
    VALUES (NEW.lead_list_id, new_id, COALESCE(NEW.created_at, now()), NULLIF(trim(NEW.source),''))
    ON CONFLICT (collection_id, entity_id) DO UPDATE
      SET source = COALESCE(EXCLUDED.source, collection_entities.source);
  END IF;

  NEW.id := new_id;
  RETURN NEW;
END;
$_$;


--
-- Name: leads_update_handler(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leads_update_handler() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  ws UUID := COALESCE(NEW.workspace_id, OLD.workspace_id);
BEGIN
  IF NEW.sent_at IS DISTINCT FROM OLD.sent_at AND NEW.sent_at IS NOT NULL THEN
    INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
    VALUES (ws, OLD.id, 'event', 'interaction.email_sent',
            jsonb_build_object('variant', NEW.send_variant), 'lead_list', 'trigger', NEW.sent_at)
    ON CONFLICT DO NOTHING;
  END IF;

  IF NEW.replied_at IS DISTINCT FROM OLD.replied_at AND NEW.replied_at IS NOT NULL THEN
    INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
    VALUES (ws, OLD.id, 'event',
            CASE NEW.reply_outcome
              WHEN 'positive'       THEN 'interaction.positive_reply'
              WHEN 'negative'       THEN 'interaction.negative_reply'
              WHEN 'do_not_contact' THEN 'interaction.do_not_contact'
              WHEN 'unsubscribed'   THEN 'interaction.unsubscribed'
              ELSE                       'interaction.reply'
            END,
            jsonb_build_object('outcome', NEW.reply_outcome), 'lead_list', 'trigger', NEW.replied_at);
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
    VALUES (ws, OLD.id, 'state', 'lead_status', to_jsonb(NEW.status), 'lead_list', 'trigger', now());
    IF NEW.status = 'bounced' THEN
      INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
      VALUES (ws, OLD.id, 'state', 'reachability_status', to_jsonb('bounced'::text), 'lead_list', 'trigger', now());
      INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
      VALUES (ws, OLD.id, 'event', 'interaction.email_bounced',
              jsonb_build_object('via','lead_status'), 'lead_list', 'trigger', now());
    END IF;
  END IF;

  IF NEW.reply_outcome IS DISTINCT FROM OLD.reply_outcome AND NEW.reply_outcome IS NOT NULL THEN
    INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
    VALUES (ws, OLD.id, 'state', 'sentiment', to_jsonb(NEW.reply_outcome::text), 'lead_list', 'trigger', now());
    IF NEW.reply_outcome = 'positive' THEN
      INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
      VALUES (ws, OLD.id, 'state', 'pipeline_stage', to_jsonb('interested'::text), 'lead_list', 'trigger', now());
    END IF;
    IF NEW.reply_outcome = 'unsubscribed' THEN
      INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
      VALUES (ws, OLD.id, 'state', 'reachability_status', to_jsonb('unsubscribed'::text), 'lead_list', 'trigger', now());
    END IF;
  END IF;

  INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
  SELECT ws, OLD.id, 'state', k.property, k.new_v, 'lead_list', 'trigger', now() FROM (VALUES
    ('send_variant',      to_jsonb(NULLIF(trim(NEW.send_variant),'')), to_jsonb(NULLIF(trim(OLD.send_variant),''))),
    ('scorecard_score',   to_jsonb(NEW.scorecard_score),                to_jsonb(OLD.scorecard_score)),
    ('is_repeat_contact', to_jsonb(NEW.is_repeat_contact),              to_jsonb(OLD.is_repeat_contact)),
    ('features',          CASE WHEN NEW.features IS NULL OR NEW.features = '{}'::jsonb THEN NULL ELSE NEW.features END,
                          CASE WHEN OLD.features IS NULL OR OLD.features = '{}'::jsonb THEN NULL ELSE OLD.features END),
    ('fields',            CASE WHEN NEW.fields IS NULL OR NEW.fields = '{}'::jsonb THEN NULL ELSE NEW.fields END,
                          CASE WHEN OLD.fields IS NULL OR OLD.fields = '{}'::jsonb THEN NULL ELSE OLD.fields END)
  ) AS k(property, new_v, old_v)
  WHERE k.new_v IS NOT NULL AND k.new_v IS DISTINCT FROM k.old_v;

  IF NEW.lead_list_id IS DISTINCT FROM OLD.lead_list_id THEN
    IF OLD.lead_list_id IS NOT NULL THEN
      DELETE FROM collection_entities WHERE collection_id = OLD.lead_list_id AND entity_id = OLD.id;
    END IF;
    IF NEW.lead_list_id IS NOT NULL THEN
      INSERT INTO collection_entities (collection_id, entity_id, added_at)
      VALUES (NEW.lead_list_id, OLD.id, now()) ON CONFLICT DO NOTHING;
    END IF;
  END IF;

  IF NEW.contact_id IS DISTINCT FROM OLD.contact_id AND NEW.contact_id IS NOT NULL THEN
    INSERT INTO observations (workspace_id, entity_id, kind, property, value, source, method, observed_at)
    VALUES (ws, OLD.id, 'state', 'graduated_to_contact_id', to_jsonb(NEW.contact_id::text), 'lead_list', 'trigger', now());
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: list_document_types(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_document_types() RETURNS TABLE(document_type text, subtype text, display_name text, page_count_range jsonb)
    LANGUAGE plpgsql STABLE
    AS $$                                                                                                                                                                                               
  BEGIN                                                                                                                                                                                                                       
    RETURN QUERY                                                                                                                                                                                                              
    SELECT dtk.document_type, dtk.subtype,                                                                                                                                                                                    
      CASE WHEN dtk.subtype IS NOT NULL THEN dtk.subtype ELSE dtk.document_type END AS display_name,                                                                                                                          
      dtk.page_count_range                                                                                                                                                                                                    
    FROM document_type_knowledge dtk                                                                                                                                                                                          
    ORDER BY dtk.document_type, CASE WHEN dtk.subtype IS NULL THEN 0 ELSE 1 END, dtk.subtype;                                                                                                                                 
  END;                                                                                                                                                                                                                        
  $$;


--
-- Name: list_row_values(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_row_values(ws uuid) RETURNS TABLE(entity_id uuid, property text, val text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH props AS (
    SELECT unnest(ARRAY['name','first_name','last_name','job_title','industry','icp_score',
                        'deal_health_score','pipeline_stage','status','value','stage','close_date',
                        'owner_name','pipeline_id','is_internal']) AS p
  ),
  cl AS (
    SELECT DISTINCT ON (c.entity_id, c.property)
           c.entity_id, c.property, COALESCE(c.value->>'value', c.value#>>'{}') AS val
      FROM claims c JOIN props ON props.p = c.property
     WHERE c.workspace_id = ws AND c.invalid_at IS NULL
     ORDER BY c.entity_id, c.property, c.computed_at DESC NULLS LAST
  ),
  ob AS (
    SELECT DISTINCT ON (o.entity_id, o.property)
           o.entity_id, o.property, COALESCE(o.value->>'value', o.value#>>'{}') AS val
      FROM observations o JOIN props ON props.p = o.property
     WHERE o.workspace_id = ws
     ORDER BY o.entity_id, o.property, o.observed_at DESC NULLS LAST
  )
  SELECT COALESCE(cl.entity_id, ob.entity_id), COALESCE(cl.property, ob.property),
         COALESCE(cl.val, ob.val)
    FROM cl FULL OUTER JOIN ob ON ob.entity_id = cl.entity_id AND ob.property = cl.property;
$$;


--
-- Name: list_rows_missing_ids(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_rows_missing_ids(ws uuid, p_kind text, p_limit integer DEFAULT 500) RETURNS TABLE(id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.id
    from entities e
   where e.workspace_id = ws
     and e.type = case p_kind when 'account' then 'company' when 'person' then 'person' else 'deal' end
     and e.status = 'active'
     and not exists (
           select 1 from entity_list_rows r
            where r.workspace_id = ws and r.entity_id = e.id and r.kind = p_kind)
     -- An entity the projection deliberately EXCLUDES is not a hole. refresh_list_chunk skips
     -- anything flagged internal and the workspace's own company (and deletes their rows if any
     -- exist), so without the same rule here the sweep chases a row that must never exist, once
     -- per tick, forever. Found immediately: after filling one customer's ~260 holes, one remained —
     -- their own company, whose domain is the workspace's own domain.
     and not exists (
           select 1 from claims c
            where c.entity_id = e.id and c.property = 'is_internal' and c.invalid_at is null
              and lower(coalesce(c.value->>'value', c.value#>>'{}')) in ('true','t','1'))
     and not exists (
           select 1 from entity_identifiers ei, workspaces w
            where ei.entity_id = e.id and ei.kind = 'domain' and ei.status = 'active'
              and w.id = ws
              and lower(ei.value) = nullif(split_part(
                    regexp_replace(lower(coalesce(w.website,'')), '^https?://(www\.)?', ''), '/', 1), ''))
   order by e.id
   limit p_limit;
$$;


--
-- Name: mark_inspirations_for_metadata_extraction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_inspirations_for_metadata_extraction() RETURNS TABLE(id uuid, image_url text, type text, category text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    bi.id,
    bi.image_url,
    bi.type,
    bi.category
  FROM background_inspirations bi
  WHERE bi.active = true
    AND (bi.style IS NULL OR bi.colors = '{}'::text[] OR bi.theme_type IS NULL)
  ORDER BY bi.created_at DESC;
END;
$$;


--
-- Name: FUNCTION mark_inspirations_for_metadata_extraction(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mark_inspirations_for_metadata_extraction() IS 'Returns all active background inspirations that need metadata extraction (style, colors, theme_type). Use this to identify which inspirations need to be processed via AI.';


--
-- Name: match_company_assets(public.vector, uuid, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_company_assets(query_embedding public.vector, workspace_id_param uuid, match_threshold double precision DEFAULT 0.2, match_count integer DEFAULT 10) RETURNS TABLE(company_asset_id uuid, chunk_text text, chunk_index integer, similarity double precision, metadata jsonb, asset_title text, asset_type text)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ca.id as company_asset_id,
    cavs.chunk_text,
    cavs.chunk_index,
    (1 - (cavs.embedding <=> query_embedding))::float as similarity,
    cavs.metadata,
    ca.title as asset_title,
    ca.type as asset_type
  FROM company_assets_vector_store cavs
  INNER JOIN company_assets ca ON cavs.company_asset_id = ca.id
  WHERE ca.workspace_id = workspace_id_param
    AND ca.status = 'completed'
    AND (1 - (cavs.embedding <=> query_embedding)) > match_threshold
  ORDER BY cavs.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


--
-- Name: match_knowledge_base(public.vector, uuid, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_knowledge_base(query_embedding public.vector, workspace_id uuid, match_threshold double precision DEFAULT 0.5, match_count integer DEFAULT 5) RETURNS TABLE(id uuid, title text, content_text text, type text, url text, file_path text, similarity double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    kb.id,
    kb.title,
    kb.content_text,
    kb.type::text,
    kb.url,
    kb.file_path,
    1 - (kb.embedding <=> query_embedding) AS similarity
  FROM knowledge_base_entries kb
  WHERE kb.workspace_id = match_knowledge_base.workspace_id
    AND kb.status = 'completed'
    AND kb.embedding IS NOT NULL
    AND 1 - (kb.embedding <=> query_embedding) > match_threshold
  ORDER BY kb.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


--
-- Name: match_knowledge_base_vector_store(public.vector, double precision, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_knowledge_base_vector_store(query_embedding public.vector, match_threshold double precision, match_count integer, template_id uuid) RETURNS TABLE(id uuid, knowledge_base_entry_id uuid, chunk_text text, chunk_index integer, embedding public.vector, similarity double precision, metadata jsonb)
    LANGUAGE plpgsql
    AS $$
#variable_conflict use_column
BEGIN
  RETURN QUERY
  SELECT
    knowledge_base_vector_store.id,
    knowledge_base_vector_store.knowledge_base_entry_id,
    knowledge_base_vector_store.chunk_text,
    knowledge_base_vector_store.chunk_index,
    knowledge_base_vector_store.embedding,
    (knowledge_base_vector_store.embedding <#> query_embedding) * -1 AS similarity,
    knowledge_base_vector_store.metadata
  FROM knowledge_base_vector_store
  INNER JOIN knowledge_base_entries ON knowledge_base_vector_store.knowledge_base_entry_id = knowledge_base_entries.id
  WHERE knowledge_base_entries.template_id = match_knowledge_base_vector_store.template_id -- Filter by template_id
    AND (knowledge_base_vector_store.embedding <#> query_embedding) * -1 > match_threshold
  ORDER BY (knowledge_base_vector_store.embedding <#> query_embedding) * -1 DESC
  LIMIT match_count;
END;
$$;


--
-- Name: match_knowledge_base_vector_store(public.vector, uuid, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_knowledge_base_vector_store(query_embedding public.vector, template_id_param uuid, match_threshold double precision, match_count integer) RETURNS TABLE(knowledge_base_entry_id uuid, chunk_text text, chunk_index integer, similarity double precision, metadata jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    kbe.id as knowledge_base_entry_id,
    kbvs.chunk_text,
    kbvs.chunk_index,
    1 - (kbvs.embedding <=> query_embedding) as similarity,
    kbvs.metadata
  FROM knowledge_base_vector_store kbvs
  INNER JOIN knowledge_base_entries kbe ON kbvs.knowledge_base_entry_id = kbe.id
  WHERE kbe.template_id = template_id_param
    AND 1 - (kbvs.embedding <=> query_embedding) > match_threshold
  ORDER BY kbvs.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


--
-- Name: match_workspace_memories(uuid, public.vector, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_workspace_memories(p_workspace_id uuid, p_embedding public.vector, p_threshold double precision, p_limit integer) RETURNS TABLE(id uuid, content text, category text, source text, similarity double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    m.id,
    m.content,
    m.category,
    m.source,
    (1 - (m.embedding <=> p_embedding))::FLOAT AS similarity
  FROM workspace_memories m
  WHERE m.workspace_id = p_workspace_id
    AND m.is_active = true
    AND m.embedding IS NOT NULL
    AND 1 - (m.embedding <=> p_embedding) >= p_threshold
  ORDER BY m.embedding <=> p_embedding
  LIMIT p_limit;
END;
$$;


--
-- Name: normalise_identifier(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalise_identifier(p_kind text, p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v      text := btrim(coalesce(p_value, ''));
  handle text;
BEGIN
  IF v = '' THEN RETURN NULL; END IF;

  IF p_kind IN ('email', 'domain') THEN
    RETURN lower(v);
  END IF;

  IF p_kind = 'linkedin_url' THEN
    handle := substring(v from '/in/([^/?#]+)');
    IF handle IS NULL OR handle = '' THEN RETURN v; END IF;   -- /company/ pages left untouched
    -- A member URN keeps its case; a vanity handle folds.
    IF handle !~* '^acoa' THEN handle := lower(handle); END IF;
    RETURN 'https://www.linkedin.com/in/' || handle;
  END IF;

  IF p_kind = 'linkedin_member_id' THEN
    IF v LIKE 'ACoA%' THEN RETURN v; END IF;                  -- real URNs are case-sensitive
    RETURN lower(v);
  END IF;

  RETURN v;
END;
$$;


--
-- Name: FUNCTION normalise_identifier(p_kind text, p_value text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.normalise_identifier(p_kind text, p_value text) IS 'Canonical form of an identifier value, by kind. Mirrors normaliseIdentifier() in @nous/core. Applied by a BEFORE INSERT OR UPDATE trigger so no write path can bypass it.';


--
-- Name: normalize_country(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_country(raw text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when raw is null or btrim(raw) = '' then null
    when lower(btrim(raw)) in ('canada','ca','can') then 'Canada'
    when lower(btrim(raw)) in ('united states','united states of america','usa','u.s.a.','us','u.s.') then 'United States'
    when lower(btrim(raw)) in ('united kingdom','uk','u.k.','great britain') then 'United Kingdom'
    else initcap(btrim(raw))
  end;
$$;


--
-- Name: people_coverage(uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.people_coverage(p_workspace uuid, p_title text DEFAULT NULL::text, p_keyword text DEFAULT NULL::text, p_stale_days integer DEFAULT 90, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  WITH matched AS (
    SELECT e.id
    FROM entities e
    WHERE e.workspace_id = p_workspace
      AND e.type = 'person' AND e.status = 'active'
      AND (p_title IS NULL OR EXISTS (
        SELECT 1 FROM claims c
        WHERE c.entity_id = e.id AND c.property = 'job_title'
          AND c.invalid_at IS NULL AND (c.value #>> '{}') ILIKE '%'||p_title||'%'))
      AND (p_keyword IS NULL OR EXISTS (
        SELECT 1 FROM claims c
        WHERE c.entity_id = e.id AND c.property IN ('job_title','company','department')
          AND c.invalid_at IS NULL AND (c.value #>> '{}') ILIKE '%'||p_keyword||'%'))
  ),
  enr AS (
    SELECT m.id,
      (SELECT max(o.observed_at) FROM observations o
         WHERE o.entity_id = m.id AND o.method = 'enrichment') AS enriched_at,
      (SELECT c.value #>> '{}' FROM claims c
         WHERE c.entity_id = m.id AND c.property = 'reachability_status'
           AND c.invalid_at IS NULL LIMIT 1) AS email_status,
      (SELECT c.value #>> '{}' FROM claims c
         WHERE c.entity_id = m.id AND c.property = 'job_title'
           AND c.invalid_at IS NULL LIMIT 1) AS job_title,
      (SELECT c.value #>> '{}' FROM claims c
         WHERE c.entity_id = m.id AND c.property = 'company'
           AND c.invalid_at IS NULL LIMIT 1) AS company
    FROM matched m
  )
  SELECT jsonb_build_object(
    'total',           (SELECT count(*) FROM enr),
    'never_enriched',  (SELECT count(*) FROM enr WHERE enriched_at IS NULL),
    'stale',           (SELECT count(*) FROM enr WHERE enriched_at IS NOT NULL
                          AND enriched_at < now() - make_interval(days => p_stale_days)),
    'fresh_verified',  (SELECT count(*) FROM enr WHERE enriched_at >= now() - make_interval(days => p_stale_days)
                          AND email_status IS NOT NULL),
    'needs_enrichment',(SELECT count(*) FROM enr WHERE enriched_at IS NULL
                          OR enriched_at < now() - make_interval(days => p_stale_days)),
    'sample', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'entity_id',   s.id,
        'job_title',   s.job_title,
        'company',     s.company,
        'enriched_at', s.enriched_at,
        'email_status', s.email_status))
      FROM (SELECT * FROM enr ORDER BY enriched_at ASC NULLS FIRST LIMIT p_limit) s
    ), '[]'::jsonb)
  );
$$;


--
-- Name: person_name_candidates(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_name_candidates(ws uuid, fname text) RETURNS TABLE(entity_id uuid, first_name text, last_name text, has_email boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    e.id,
    lower(f.value #>> '{}'),
    lower(l.value #>> '{}'),
    EXISTS (
      SELECT 1 FROM entity_identifiers i
       WHERE i.entity_id = e.id AND i.kind = 'email' AND i.status = 'active'
    )
  FROM claims f
  JOIN entities e
    ON e.id = f.entity_id
   AND e.workspace_id = ws
   AND e.type = 'person'
   AND e.status = 'active'
  LEFT JOIN claims l
    ON l.entity_id = e.id
   AND l.workspace_id = ws
   AND l.property = 'last_name'
   AND l.invalid_at IS NULL
  WHERE f.workspace_id = ws
    AND f.property = 'first_name'
    AND f.invalid_at IS NULL
    AND lower(f.value #>> '{}') = lower(fname)
  LIMIT 200;
$$;


--
-- Name: FUNCTION person_name_candidates(ws uuid, fname text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_name_candidates(ws uuid, fname text) IS 'People in this workspace whose first name matches, for the identity-resolution name fallback. Replaces a client-side scan that truncated the workspace at 5000 unordered claim rows. 200 is a genuine ceiling: a first name shared by 200 active people corroborates nothing, so the caller treats that as ambiguous and refuses to match.';


--
-- Name: prune_api_request_log(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_api_request_log(p_retain_days integer DEFAULT 90, p_batch integer DEFAULT 20000) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare n int;
begin
  delete from public.api_request_log
   where id in (
     select id from public.api_request_log
      where at < now() - make_interval(days => greatest(p_retain_days, 1))
      limit greatest(p_batch, 1)
   );
  get diagnostics n = row_count;
  return n;
end;
$$;


--
-- Name: recalculate_all_completion_rates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_all_completion_rates() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_doc RECORD;
  v_total_pages INTEGER;
  v_first_session_id TEXT;
  v_highest_page_first_session INTEGER;
  v_new_completion_rate INTEGER;
  v_existing_completion_rate INTEGER;
BEGIN
  -- Loop through all documents that have analytics events
  FOR v_doc IN 
    SELECT DISTINCT document_id 
    FROM document_analytics_events
  LOOP
    -- Get total pages for document (count page_break blocks + 1)
    SELECT (SELECT COUNT(*) FROM jsonb_array_elements(d.document_blocks) AS block WHERE (block->>'block_type') = 'page_break') + 1
    INTO v_total_pages
    FROM documents d
    WHERE d.id = v_doc.document_id;
    
    -- If total_pages calculation failed, use a simple heuristic
    IF v_total_pages IS NULL OR v_total_pages = 0 THEN
      SELECT COALESCE(MAX(page_number), 1) INTO v_total_pages
      FROM document_analytics_events
      WHERE document_id = v_doc.document_id AND event_type = 'viewed';
      
      IF v_total_pages IS NULL OR v_total_pages = 0 THEN
        v_total_pages := 1;
      END IF;
    END IF;
    
    -- Find the first session (earliest 'opened' event)
    SELECT session_id
    INTO v_first_session_id
    FROM document_analytics_events
    WHERE document_id = v_doc.document_id 
      AND event_type = 'opened'
    ORDER BY created_at ASC
    LIMIT 1;
    
    -- If we have a first session, get the highest page viewed in that session
    IF v_first_session_id IS NOT NULL THEN
      SELECT COALESCE(MAX(page_number), 0)
      INTO v_highest_page_first_session
      FROM document_analytics_events
      WHERE document_id = v_doc.document_id 
        AND session_id = v_first_session_id
        AND event_type = 'viewed'
        AND page_number IS NOT NULL;
      
      -- Calculate completion rate: (highest_page / total_pages) * 100
      IF v_highest_page_first_session > 0 AND v_total_pages > 0 THEN
        v_new_completion_rate := ROUND((v_highest_page_first_session::DECIMAL / v_total_pages::DECIMAL) * 100);
        IF v_new_completion_rate > 100 THEN
          v_new_completion_rate := 100;
        END IF;
      ELSE
        v_new_completion_rate := 0;
      END IF;
    ELSE
      v_new_completion_rate := 0;
    END IF;
    
    -- Get existing completion rate
    SELECT COALESCE(completion_rate, 0)
    INTO v_existing_completion_rate
    FROM document_analytics
    WHERE document_id = v_doc.document_id;
    
    -- Only update if new rate is higher (never decrease)
    IF v_new_completion_rate > v_existing_completion_rate THEN
      UPDATE document_analytics
      SET completion_rate = v_new_completion_rate,
          updated_at = NOW()
      WHERE document_id = v_doc.document_id;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: refresh_entity_list_rows(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_entity_list_rows(ws uuid) RETURNS TABLE(accounts integer, people integer, deals integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '600s'
    AS $$
DECLARE n_accounts integer := 0; n_people integer := 0; n_deals integer := 0; own_domain text;
BEGIN
  SELECT nullif(regexp_replace(lower(coalesce(w.website,'')), '^https?://(www\.)?', ''), '')
    INTO own_domain FROM workspaces w WHERE w.id = ws;
  own_domain := split_part(coalesce(own_domain,''), '/', 1);

  -- Claim where derived, newest observation where not (GET-303).
  CREATE TEMP TABLE _c ON COMMIT DROP AS SELECT * FROM list_row_values(ws);
  CREATE INDEX ON _c (entity_id, property);

  CREATE TEMP TABLE _at ON COMMIT DROP AS
  SELECT r.from_entity_id AS person_id, r.to_entity_id AS company_id FROM relationships r
   WHERE r.workspace_id = ws AND r.type = 'works_at' AND r.valid_to IS NULL;
  CREATE INDEX ON _at (person_id); CREATE INDEX ON _at (company_id);

  CREATE TEMP TABLE _internal ON COMMIT DROP AS
  SELECT ic.entity_id FROM _c ic WHERE ic.property='is_internal' AND lower(ic.val) IN ('true','t','1')
  UNION
  SELECT ei.entity_id FROM entity_identifiers ei
   WHERE ei.kind='domain' AND ei.status='active' AND own_domain <> '' AND lower(ei.value)=own_domain
     AND EXISTS (SELECT 1 FROM entities e WHERE e.id=ei.entity_id AND e.workspace_id=ws);
  INSERT INTO _internal SELECT a.person_id FROM _at a JOIN _internal i ON i.entity_id=a.company_id;
  CREATE INDEX ON _internal (entity_id);

  CREATE TEMP TABLE _act ON COMMIT DROP AS
  SELECT o.entity_id, max(o.observed_at) AS last_at FROM observations o
   WHERE o.workspace_id = ws AND o.property LIKE 'interaction.%' GROUP BY o.entity_id;
  CREATE INDEX ON _act (entity_id);

  CREATE TEMP TABLE _belongs ON COMMIT DROP AS
  SELECT b.from_entity_id AS deal_id, b.to_entity_id AS company_id FROM relationships b
   WHERE b.workspace_id = ws AND b.type='belongs_to';
  CREATE INDEX ON _belongs (deal_id); CREATE INDEX ON _belongs (company_id);

  CREATE TEMP TABLE _deals ON COMMIT DROP AS
  SELECT bl.company_id,
         count(*) FILTER (WHERE ds.val='open') AS open_deals,
         sum(nullif(dv.val,'')::numeric) FILTER (WHERE ds.val='open') AS pipeline_value,
         sum(nullif(dv.val,'')::numeric) FILTER (WHERE ds.val='won') AS won_value
    FROM _belongs bl JOIN entities de ON de.id=bl.deal_id AND de.type='deal'
    LEFT JOIN _c ds ON ds.entity_id=de.id AND ds.property='status'
    LEFT JOIN _c dv ON dv.entity_id=de.id AND dv.property='value'
   GROUP BY bl.company_id;
  CREATE INDEX ON _deals (company_id);

  DELETE FROM entity_list_rows WHERE workspace_id = ws;

  INSERT INTO entity_list_rows (workspace_id, entity_id, kind, name, domain, industry, icp_score,
                                deal_health, people_count, open_deals, pipeline_value, won_value, last_activity_at)
  SELECT ws, e.id, 'account', nm.val,
         (SELECT ei.value FROM entity_identifiers ei WHERE ei.entity_id=e.id AND ei.kind='domain' AND ei.status='active' LIMIT 1),
         ind.val, nullif(icp.val,'')::numeric::integer, nullif(dh.val,'')::numeric::integer,
         coalesce(pc.n,0), coalesce(d.open_deals,0), d.pipeline_value, d.won_value,
         greatest(own.last_at, ppl.last_at)
    FROM entities e
    LEFT JOIN _c nm ON nm.entity_id=e.id AND nm.property='name'
    LEFT JOIN _c ind ON ind.entity_id=e.id AND ind.property='industry'
    LEFT JOIN _c icp ON icp.entity_id=e.id AND icp.property='icp_score'
    LEFT JOIN _c dh ON dh.entity_id=e.id AND dh.property='deal_health_score'
    LEFT JOIN _deals d ON d.company_id=e.id
    LEFT JOIN _act own ON own.entity_id=e.id
    LEFT JOIN LATERAL (SELECT count(*) AS n FROM _at a WHERE a.company_id=e.id) pc ON true
    LEFT JOIN LATERAL (SELECT max(x.last_at) AS last_at FROM _at a JOIN _act x ON x.entity_id=a.person_id WHERE a.company_id=e.id) ppl ON true
   WHERE e.workspace_id=ws AND e.type='company' AND e.status='active'
     AND NOT EXISTS (SELECT 1 FROM _internal i WHERE i.entity_id=e.id);
  GET DIAGNOSTICS n_accounts = ROW_COUNT;

  INSERT INTO entity_list_rows (workspace_id, entity_id, kind, name, email, job_title, company_id,
                                company_name, stage, icp_score, last_activity_at)
  SELECT ws, e.id, 'person',
         nullif(trim(coalesce(fn.val,'') || ' ' || coalesce(ln.val,'')), ''),
         (SELECT ei.value FROM entity_identifiers ei WHERE ei.entity_id=e.id AND ei.kind='email' AND ei.status='active' LIMIT 1),
         jt.val, a.company_id, cn.name, st.val, nullif(icp.val,'')::numeric::integer, act.last_at
    FROM entities e
    LEFT JOIN _c fn ON fn.entity_id=e.id AND fn.property='first_name'
    LEFT JOIN _c ln ON ln.entity_id=e.id AND ln.property='last_name'
    LEFT JOIN _c jt ON jt.entity_id=e.id AND jt.property='job_title'
    LEFT JOIN _c st ON st.entity_id=e.id AND st.property='pipeline_stage'
    LEFT JOIN _c icp ON icp.entity_id=e.id AND icp.property='icp_score'
    LEFT JOIN _at a ON a.person_id=e.id
    LEFT JOIN entity_list_rows cn ON cn.workspace_id=ws AND cn.entity_id=a.company_id AND cn.kind='account'
    LEFT JOIN _act act ON act.entity_id=e.id
   WHERE e.workspace_id=ws AND e.type='person' AND e.status='active'
     AND NOT EXISTS (SELECT 1 FROM _internal i WHERE i.entity_id=e.id);
  GET DIAGNOSTICS n_people = ROW_COUNT;

  INSERT INTO entity_list_rows (workspace_id, entity_id, kind, name, company_id, company_name, stage,
                                status, pipeline_value, close_date, owner_name, pipeline_ref, last_activity_at)
  SELECT ws, e.id, 'deal', nm.val, bl.company_id, cn.name, stg.val, st.val,
         nullif(dv.val,'')::numeric,
         CASE WHEN cd.val ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' THEN cd.val::timestamptz END,
         own.val, pid.val, cn.last_activity_at
    FROM entities e
    LEFT JOIN _c nm ON nm.entity_id=e.id AND nm.property='name'
    LEFT JOIN _c stg ON stg.entity_id=e.id AND stg.property='stage'
    LEFT JOIN _c st ON st.entity_id=e.id AND st.property='status'
    LEFT JOIN _c dv ON dv.entity_id=e.id AND dv.property='value'
    LEFT JOIN _c cd ON cd.entity_id=e.id AND cd.property='close_date'
    LEFT JOIN _c own ON own.entity_id=e.id AND own.property='owner_name'
    LEFT JOIN _c pid ON pid.entity_id=e.id AND pid.property='pipeline_id'
    LEFT JOIN _belongs bl ON bl.deal_id=e.id
    LEFT JOIN entity_list_rows cn ON cn.workspace_id=ws AND cn.entity_id=bl.company_id AND cn.kind='account'
   WHERE e.workspace_id=ws AND e.type='deal' AND e.status='active';
  GET DIAGNOSTICS n_deals = ROW_COUNT;

  RETURN QUERY SELECT n_accounts, n_people, n_deals;
END; $$;


--
-- Name: refresh_list_chunk(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_list_chunk(ws uuid, p_kind text, p_after uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid, p_limit integer DEFAULT 400) RETURNS TABLE(processed integer, last_id uuid)
    LANGUAGE plpgsql
    AS $_$
declare
  n integer := 0;
  last uuid;
  own_domain text;
  entity_type text := case p_kind when 'account' then 'company' when 'person' then 'person' else 'deal' end;
  props text[] := array['name','first_name','last_name','job_title','industry','icp_score',
                        'deal_health_score','pipeline_stage','status','value','stage',
                        'close_date','owner_name','owner_email','pipeline','pipeline_id','is_internal','location'];
begin
  select nullif(split_part(regexp_replace(lower(coalesce(w.website,'')), '^https?://(www\.)?', ''), '/', 1), '')
    into own_domain from workspaces w where w.id = ws;

  -- ON COMMIT DROP only fires at commit, so a second call inside one transaction fails with
  -- "relation _ids already exists". Each call starts from a clean slate instead.
  drop table if exists _ids, _v, _act, _staff, _deals, _childdeals, _cs;

  create temp table _ids on commit drop as
  select e.id from entities e
   where e.workspace_id = ws and e.type = entity_type and e.status = 'active' and e.id > p_after
   order by e.id limit p_limit;
  create unique index on _ids (id);
  analyze _ids;
  select count(*) into n from _ids;
  select id into last from _ids order by id desc limit 1;
  if n = 0 then return query select 0, p_after; return; end if;

  -- Claim first, observation second: pri 0 outranks pri 1, then newest wins.
  create temp table _v on commit drop as
  select distinct on (u.entity_id, u.prop) u.entity_id, u.prop, u.val
    from (
      select cl.entity_id, cl.property as prop,
             coalesce(cl.value->>'value', cl.value#>>'{}') as val, 0 as pri, cl.computed_at as at
        from claims cl join _ids i on i.id = cl.entity_id
       where cl.invalid_at is null and cl.property = any(props)
      union all
      select ob.entity_id, ob.property,
             coalesce(ob.value->>'value', ob.value#>>'{}'), 1, ob.observed_at
        from observations ob join _ids i on i.id = ob.entity_id
       where ob.property = any(props)
    ) u
   order by u.entity_id, u.prop, u.pri, u.at desc nulls last;
  create index on _v (entity_id, prop);
  analyze _v;

  -- LAST activity, so only what has already happened. A booked meeting is stored as an
  -- interaction at its start time, and plenty of them sit in the future (some months ahead),
  -- which sorted those accounts to the top of a list ordered by "last activity" and printed a date
  -- that had not arrived yet. Upcoming meetings belong to a next-meeting field, not this one.
  create temp table _act on commit drop as
  select ob.entity_id,
         max(ob.observed_at) filter (where ob.observed_at <= now()) as at,
         -- The last time they came to US. Deliberately NOT capped at now(): a meeting booked for
         -- next week is the strongest engagement signal an account can carry, and the cap above
         -- exists to stop a future meeting being printed as "last activity", not to deny it ever
         -- happened. A no-show counts — they agreed to the meeting.
         max(ob.observed_at) filter (where ob.property in (
               'interaction.email_received', 'interaction.call_received',
               'interaction.meeting_held',   'interaction.meeting_no_show',
               'interaction.meeting_scheduled')) as inbound_at
    from observations ob join _ids i on i.id = ob.entity_id
   where ob.property like 'interaction.%'
   group by ob.entity_id;
  create unique index on _act (entity_id);
  analyze _act;

  -- A deal's activity is the conversation ABOUT it. Deals carry no interaction observations of
  -- their own, so every deal row had a blank last-activity column; the link lives in
  -- observation_deals.
  if p_kind = 'deal' then
    create temp table _dact on commit drop as
    select od.deal_entity_id as deal_id, max(ob.observed_at) as at
      from observation_deals od
      join _ids i on i.id = od.deal_entity_id
      join observations ob on ob.id = od.observation_id
     where od.workspace_id = ws and ob.observed_at <= now()
     group by od.deal_entity_id;
    create unique index on _dact (deal_id);
    analyze _dact;
  end if;

  if p_kind = 'account' then
    create temp table _staff on commit drop as
    select r.to_entity_id as account_id, count(*) as people_count,
           max(pl.last_activity_at) as at, max(pl.last_inbound_at) as inbound_at
      from relationships r
      join _ids i on i.id = r.to_entity_id
      left join entity_list_rows pl
        on pl.workspace_id = ws and pl.entity_id = r.from_entity_id and pl.kind = 'person'
     where r.workspace_id = ws and r.type = 'works_at' and r.valid_to is null
     group by r.to_entity_id;
    create unique index on _staff (account_id);
    analyze _staff;

    create temp table _deals on commit drop as
    select dl.company_id as account_id,
           count(*) filter (where dl.status = 'open') as open_deals,
           sum(dl.pipeline_value) filter (where dl.status = 'open') as pipeline_value,
           sum(dl.pipeline_value) filter (where dl.status = 'won') as won_value,
           count(*) filter (where dl.status = 'won') as won_deals,
           max(dl.close_date) filter (where dl.status = 'lost') as last_lost_at
      from entity_list_rows dl
      join _ids i on i.id = dl.company_id
     where dl.workspace_id = ws and dl.kind = 'deal'
     group by dl.company_id;
    create unique index on _deals (account_id);
    analyze _deals;

    -- A company group holds no deals of its own; its locations do. Quillmere Holdings
    -- (quillmere-holdings.example) has five, and about a third of one customer's group parents are in that
    -- shape. Without this the has-a-deal rule would hide exactly the record a rep needs in
    -- order to see the group at all.
    create temp table _childdeals on commit drop as
    select r.to_entity_id as account_id, count(*) as child_deals
      from relationships r
      join entity_list_rows dl
        on dl.workspace_id = ws and dl.kind = 'deal' and dl.company_id = r.from_entity_id
      join _ids i on i.id = r.to_entity_id
     where r.workspace_id = ws and r.type = 'subsidiary_of' and r.valid_to is null
     group by r.to_entity_id;
    create unique index on _childdeals (account_id);
    analyze _childdeals;

    -- Account health, exactly as the customer's own CRM keeps it (the cs.* claims the sync
    -- writes; see packages/core/src/integrations/crm/accountHealth.ts). Kept as JSONB rather than
    -- flattened to text like _v, because three of these facts are arrays — products, risk_signals,
    -- goals — and #>>'{}' on an array yields the literal string '["a","b"]' for every reader to
    -- re-parse. Claims only, with no observation fallback: a cs.* observation that has not settled
    -- yet is a fact in flight, and a half-written bag reads worse on the CS page than a missing
    -- one (an account showing a status and no MRR looks like a $0 customer, not a loading row).
    create temp table _cs on commit drop as
    select v.entity_id, jsonb_object_agg(v.prop, v.val) as cs
      from (
        select distinct on (cl.entity_id, cl.property)
               cl.entity_id, substr(cl.property, 4) as prop,
               coalesce(cl.value->'value', cl.value) as val
          from claims cl join _ids i on i.id = cl.entity_id
         where cl.invalid_at is null
           and cl.property like 'cs.%' and length(cl.property) > 3
         order by cl.entity_id, cl.property, cl.computed_at desc nulls last
      ) v
     where v.val is not null and v.val <> 'null'::jsonb
     group by v.entity_id;
    create unique index on _cs (entity_id);
    analyze _cs;

    insert into entity_list_rows (workspace_id, entity_id, kind, name, domain, industry, country, icp_score, deal_health, people_count, open_deals, pipeline_value, won_value, owner_name, owner_email, won_deals, last_lost_at, child_deals, cs, last_activity_at, last_inbound_at, refreshed_at)
    select ws, i.id, 'account',
           v.name, ident.value, v.industry,
           normalize_country(nullif(trim(split_part(v.location, ',', array_length(string_to_array(v.location, ','), 1))), '')),
           nullif(v.icp_score,'')::numeric::integer,
           nullif(v.deal_health_score,'')::numeric::integer,
           coalesce(s.people_count, 0),
           coalesce(d.open_deals, 0), d.pipeline_value, d.won_value,
           v.owner_name, v.owner_email,
           coalesce(d.won_deals, 0), d.last_lost_at, coalesce(c.child_deals, 0),
           csb.cs,
           greatest(a.at, s.at),
           greatest(a.inbound_at, s.inbound_at),
           now()
      from _ids i
      left join lateral (select
             max(val) filter (where prop='name') as name,
             max(val) filter (where prop='industry') as industry,
             max(val) filter (where prop='icp_score') as icp_score,
             max(val) filter (where prop='deal_health_score') as deal_health_score,
             max(val) filter (where prop='owner_name') as owner_name,
             max(val) filter (where prop='owner_email') as owner_email,
             max(val) filter (where prop='is_internal') as is_internal,
             max(val) filter (where prop='location') as location
           from _v where entity_id = i.id) v on true
      left join _act a on a.entity_id = i.id
      left join _staff s on s.account_id = i.id
      left join _deals d on d.account_id = i.id
      left join _childdeals c on c.account_id = i.id
      left join _cs csb on csb.entity_id = i.id
      left join lateral (select ei.value from entity_identifiers ei
             where ei.entity_id=i.id and ei.kind='domain' and ei.status='active' limit 1) ident on true
     where lower(coalesce(v.is_internal,'')) not in ('true','t','1')
       and not (own_domain is not null and lower(coalesce(ident.value,'')) = own_domain)
    on conflict (workspace_id, entity_id) do update set
      name=excluded.name, domain=excluded.domain, industry=excluded.industry, country=excluded.country, icp_score=excluded.icp_score,
      deal_health=excluded.deal_health, people_count=excluded.people_count, open_deals=excluded.open_deals,
      pipeline_value=excluded.pipeline_value, won_value=excluded.won_value,
      owner_name=excluded.owner_name, owner_email=excluded.owner_email,
      won_deals=excluded.won_deals, last_lost_at=excluded.last_lost_at, child_deals=excluded.child_deals,
      cs=excluded.cs,
      last_activity_at=excluded.last_activity_at, last_inbound_at=excluded.last_inbound_at, refreshed_at=now()
    where (entity_list_rows.name, entity_list_rows.domain, entity_list_rows.industry, entity_list_rows.country, entity_list_rows.icp_score,
           entity_list_rows.deal_health, entity_list_rows.people_count, entity_list_rows.open_deals,
           entity_list_rows.pipeline_value, entity_list_rows.won_value,
           entity_list_rows.owner_name, entity_list_rows.owner_email,
           entity_list_rows.won_deals, entity_list_rows.last_lost_at, entity_list_rows.child_deals,
           entity_list_rows.cs,
           entity_list_rows.last_activity_at, entity_list_rows.last_inbound_at)
       is distinct from
          (excluded.name, excluded.domain, excluded.industry, excluded.country, excluded.icp_score,
           excluded.deal_health, excluded.people_count, excluded.open_deals,
           excluded.pipeline_value, excluded.won_value,
           excluded.owner_name, excluded.owner_email,
           excluded.won_deals, excluded.last_lost_at, excluded.child_deals,
           excluded.cs,
           excluded.last_activity_at, excluded.last_inbound_at);

    -- An account that no longer belongs in the list must LEAVE it. The insert skips the
    -- workspace's own company and anything flagged internal, but skipping only means "do not
    -- write": the row written before the rule existed stayed, so one customer's own company sat in
    -- their account list with a stale date long after the rule was added. Exclusion has to delete.
    delete from entity_list_rows r using _ids i
     where r.workspace_id = ws and r.entity_id = i.id and r.kind = 'account'
       and (exists (select 1 from _v x where x.entity_id = i.id and x.prop = 'is_internal' and lower(x.val) in ('true','t','1'))
            or (own_domain is not null and exists (
                  select 1 from entity_identifiers ei
                   where ei.entity_id = i.id and ei.kind = 'domain' and ei.status = 'active'
                     and lower(ei.value) = own_domain)));

  elsif p_kind = 'person' then
    insert into entity_list_rows (workspace_id, entity_id, kind, name, email, job_title, company_id, company_name, country, stage, icp_score, last_activity_at, last_inbound_at, refreshed_at)
    select ws, i.id, 'person',
           nullif(trim(coalesce(v.first_name,'') || ' ' || coalesce(v.last_name,'')), ''),
           ident.value, v.job_title, r.to_entity_id,
           (select l.name from entity_list_rows l where l.workspace_id=ws and l.entity_id=r.to_entity_id and l.kind='account'),
           -- A person is in the market their employer is in, so People filters by the same country
           -- the account list does. Someone with no employer has no country and stays in the focus.
           (select l.country from entity_list_rows l where l.workspace_id=ws and l.entity_id=r.to_entity_id and l.kind='account'),
           v.pipeline_stage,
           nullif(v.icp_score,'')::numeric::integer,
           a.at, a.inbound_at, now()
      from _ids i
      left join lateral (select
             max(val) filter (where prop='first_name') as first_name,
             max(val) filter (where prop='last_name') as last_name,
             max(val) filter (where prop='job_title') as job_title,
             max(val) filter (where prop='pipeline_stage') as pipeline_stage,
             max(val) filter (where prop='icp_score') as icp_score,
             max(val) filter (where prop='is_internal') as is_internal
           from _v where entity_id = i.id) v on true
      left join _act a on a.entity_id = i.id
      left join lateral (select r2.to_entity_id from relationships r2
             where r2.workspace_id=ws and r2.type='works_at' and r2.from_entity_id=i.id and r2.valid_to is null limit 1) r on true
      left join lateral (select ei.value from entity_identifiers ei
             where ei.entity_id=i.id and ei.kind='email' and ei.status='active' limit 1) ident on true
     where lower(coalesce(v.is_internal,'')) not in ('true','t','1')
    on conflict (workspace_id, entity_id) do update set
      name=excluded.name, email=excluded.email, job_title=excluded.job_title, company_id=excluded.company_id,
      company_name=excluded.company_name, country=excluded.country, stage=excluded.stage, icp_score=excluded.icp_score,
      last_activity_at=excluded.last_activity_at, last_inbound_at=excluded.last_inbound_at, refreshed_at=now()
    where (entity_list_rows.name, entity_list_rows.email, entity_list_rows.job_title, entity_list_rows.company_id,
           entity_list_rows.company_name, entity_list_rows.country, entity_list_rows.stage, entity_list_rows.icp_score, entity_list_rows.last_activity_at, entity_list_rows.last_inbound_at)
       is distinct from
          (excluded.name, excluded.email, excluded.job_title, excluded.company_id,
           excluded.company_name, excluded.country, excluded.stage, excluded.icp_score, excluded.last_activity_at,
           excluded.last_inbound_at);

  else
    insert into entity_list_rows (workspace_id, entity_id, kind, name, company_id, company_name, country, stage, status, pipeline_value, close_date, owner_name, pipeline_ref, pipeline, last_activity_at, refreshed_at)
    select ws, i.id, 'deal',
           v.name, b.to_entity_id,
           (select l.name from entity_list_rows l where l.workspace_id=ws and l.entity_id=b.to_entity_id and l.kind='account'),
           (select l.country from entity_list_rows l where l.workspace_id=ws and l.entity_id=b.to_entity_id and l.kind='account'),
           v.stage, v.status,
           nullif(v.value,'')::numeric,
           case when v.close_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' then v.close_date::timestamptz end,
           v.owner_name, v.pipeline_id, v.pipeline, greatest(a.at, da.at), now()
      from _ids i
      left join lateral (select
             max(val) filter (where prop='name') as name,
             max(val) filter (where prop='stage') as stage,
             max(val) filter (where prop='status') as status,
             max(val) filter (where prop='value') as value,
             max(val) filter (where prop='close_date') as close_date,
             max(val) filter (where prop='owner_name') as owner_name,
             max(val) filter (where prop='pipeline_id') as pipeline_id,
             max(val) filter (where prop='pipeline') as pipeline
           from _v where entity_id = i.id) v on true
      left join _act a on a.entity_id = i.id
      left join _dact da on da.deal_id = i.id
      left join lateral (select b2.to_entity_id from relationships b2
             where b2.workspace_id=ws and b2.type='belongs_to' and b2.from_entity_id=i.id limit 1) b on true
    on conflict (workspace_id, entity_id) do update set
      name=excluded.name, company_id=excluded.company_id, company_name=excluded.company_name, country=excluded.country,
      stage=excluded.stage, status=excluded.status, pipeline_value=excluded.pipeline_value,
      close_date=excluded.close_date, owner_name=excluded.owner_name, pipeline_ref=excluded.pipeline_ref,
      pipeline=excluded.pipeline,
      last_activity_at=excluded.last_activity_at, refreshed_at=now()
    where (entity_list_rows.name, entity_list_rows.company_id, entity_list_rows.company_name, entity_list_rows.country,
           entity_list_rows.stage, entity_list_rows.status, entity_list_rows.pipeline_value,
           entity_list_rows.close_date, entity_list_rows.owner_name, entity_list_rows.pipeline_ref,
           entity_list_rows.pipeline, entity_list_rows.last_activity_at)
       is distinct from
          (excluded.name, excluded.company_id, excluded.company_name, excluded.country,
           excluded.stage, excluded.status, excluded.pipeline_value,
           excluded.close_date, excluded.owner_name, excluded.pipeline_ref,
           excluded.pipeline, excluded.last_activity_at);
  end if;

  return query select n, last;
end;
$_$;


--
-- Name: refresh_list_rows_for(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_list_rows_for(ws uuid, p_kind text, p_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  i uuid;
  prev uuid;
  n integer := 0;
  etype text := case p_kind when 'account' then 'company' when 'person' then 'person' else 'deal' end;
begin
  foreach i in array coalesce(p_ids, '{}'::uuid[]) loop
    if not exists (
      select 1 from entities e
       where e.id = i and e.workspace_id = ws and e.type = etype and e.status = 'active'
    ) then
      continue;
    end if;

    select e.id into prev
      from entities e
     where e.workspace_id = ws and e.type = etype and e.status = 'active' and e.id < i
     order by e.id desc
     limit 1;

    perform refresh_list_chunk(ws, p_kind, coalesce(prev, '00000000-0000-0000-0000-000000000000'::uuid), 1);
    n := n + 1;
  end loop;
  return n;
end $$;


--
-- Name: refresh_team_account_usage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_team_account_usage(t uuid) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
  INSERT INTO team_account_usage (team_id, used, computed_at)
  SELECT t, COUNT(*), now()
    FROM entity_list_rows r
    JOIN workspaces w ON w.id = r.workspace_id AND w.team_id = t
   WHERE r.kind = 'account' AND r.last_activity_at IS NOT NULL
  ON CONFLICT (team_id) DO UPDATE SET used = EXCLUDED.used, computed_at = EXCLUDED.computed_at
  RETURNING used;
$$;


--
-- Name: reject_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  DECLARE probe observations%ROWTYPE;
  BEGIN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'observations are append-only — DELETE is not permitted';
    END IF;
    probe := NEW; probe.embedding := OLD.embedding;
    IF ROW(probe.*) IS DISTINCT FROM ROW(OLD.*) THEN
      RAISE EXCEPTION 'observations are append-only — only the embedding index may change';
    END IF;
    RETURN NEW;
  END; $$;


--
-- Name: run_invariants(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_invariants(ws uuid) RETURNS TABLE(name text, violations bigint, sample jsonb, description text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
WITH
person_without_identifier AS (
  SELECT e.id AS entity_id
    FROM entities e
   WHERE e.workspace_id = ws AND e.type = 'person' AND e.status = 'active'
     AND NOT EXISTS (SELECT 1 FROM entity_identifiers i
                      WHERE i.entity_id = e.id AND i.status = 'active')
),
identifier_not_canonical AS (
  SELECT i.id, i.entity_id, i.kind, i.value
    FROM entity_identifiers i
   WHERE i.workspace_id = ws AND i.status = 'active'
     AND i.value IS DISTINCT FROM normalise_identifier(i.kind, i.value)
),
identifier_malformed_email AS (
  SELECT i.id, i.entity_id, i.value
    FROM entity_identifiers i
   WHERE i.workspace_id = ws AND i.status = 'active' AND i.kind = 'email'
     AND i.value !~ '^[^@[:space:],;]+@[^@[:space:],;]+\.[a-z]{2,}$'
),
company_domain_unreadable AS (
  SELECT e.id AS entity_id, i.value AS domain
    FROM entities e
    JOIN entity_identifiers i
      ON i.entity_id = e.id AND i.kind = 'domain' AND i.status = 'active'
   WHERE e.workspace_id = ws AND e.type = 'company' AND e.status = 'active'
     AND NOT EXISTS (SELECT 1 FROM claims c
                      WHERE c.entity_id = e.id AND c.property = 'domain'
                        AND c.invalid_at IS NULL)
),
company_without_identifier AS (
  SELECT e.id AS entity_id
    FROM entities e
   WHERE e.workspace_id = ws AND e.type = 'company' AND e.status = 'active'
     AND NOT EXISTS (SELECT 1 FROM entity_identifiers i
                      WHERE i.entity_id = e.id AND i.status = 'active')
),
named_people AS (
  SELECT e.id,
         lower(trim(
           coalesce((SELECT value #>> '{}' FROM claims WHERE entity_id = e.id AND property = 'first_name' AND invalid_at IS NULL LIMIT 1), '')
           || ' ' ||
           coalesce((SELECT value #>> '{}' FROM claims WHERE entity_id = e.id AND property = 'last_name'  AND invalid_at IS NULL LIMIT 1), '')
         )) AS full_name
    FROM entities e
   WHERE e.workspace_id = ws AND e.type = 'person' AND e.status = 'active'
),
duplicate_people_by_name AS (
  SELECT full_name, count(*) AS copies, array_agg(id) AS entity_ids
    FROM named_people
   WHERE length(full_name) > 3
   GROUP BY full_name
  HAVING count(*) > 1
),
claim_does_not_name_its_subject AS (
  -- Only judged for facts about the PERSON. A fact tagged about:"company" names
  -- the company by design ("Corvane raised from Tallis Partners") and mentions
  -- nobody, so holding it to this rule would flag every correct company fact.
  SELECT c.id, c.entity_id, c.value->>'content' AS content
    FROM claims c
    JOIN entities e ON e.id = c.entity_id AND e.type = 'person'
   WHERE c.workspace_id = ws
     AND c.property LIKE 'note.%' AND c.invalid_at IS NULL
     AND c.value->>'source' = 'signal_extraction'
     AND coalesce(c.value->'metadata'->>'about', 'person') = 'person'
     -- Only where we actually know a name to check against; no name means the
     -- check has nothing to say, not that the claim is wrong.
     AND EXISTS (SELECT 1 FROM claims n
                  WHERE n.entity_id = e.id AND n.property = 'first_name'
                    AND n.invalid_at IS NULL AND length(n.value #>> '{}') >= 3)
     AND NOT EXISTS (
           SELECT 1 FROM claims n
            WHERE n.entity_id = e.id AND n.property IN ('first_name', 'last_name')
              AND n.invalid_at IS NULL AND length(n.value #>> '{}') >= 3
              AND position(lower(n.value #>> '{}') IN lower(c.value->>'content')) > 0)
),
unresolved_queue_actually_resolved AS (
  SELECT u.id, u.title, u.external_id
    FROM unresolved_ingest u
   WHERE u.workspace_id = ws AND u.status = 'pending'
     AND EXISTS (SELECT 1 FROM observations o
                  WHERE o.workspace_id = u.workspace_id
                    AND o.property = 'interaction.meeting_held'
                    AND o.external_id LIKE 'ff_' || u.external_id || '_%')
),
system_note_rendered_as_intel AS (
  SELECT c.id, c.entity_id, c.value->>'content' AS content
    FROM claims c
   WHERE c.workspace_id = ws
     AND c.property LIKE 'note.%' AND c.invalid_at IS NULL
     AND c.value->>'category' = 'Data Quality'
),
identifier_unreadable AS (
  -- The same write-only shape as company domains, and far bigger: most of the
  -- active people in a typical workspace hold a linkedin_url IDENTIFIER and no
  -- linkedin_url CLAIM. They are perfectly resolvable and the page shows blank,
  -- because the UI and the agent read claims. Attaching an identifier and
  -- asserting the claim are one act, not two.
  SELECT i.entity_id, i.kind, i.value
    FROM entity_identifiers i
    JOIN entities e ON e.id = i.entity_id AND e.status = 'active'
   WHERE i.workspace_id = ws AND i.status = 'active'
     AND i.kind IN ('email', 'linkedin_url', 'domain')
     AND NOT EXISTS (SELECT 1 FROM claims c
                      WHERE c.entity_id = i.entity_id AND c.property = i.kind
                        AND c.invalid_at IS NULL)
),
merged_entity_still_resolvable AS (
  -- An identifier left active on a merged record resolves to a tombstone that every
  -- view hides, so whatever is written next vanishes; with no merged_into pointer it
  -- also blocks the identifier from ever being re-attached to a live record. Six
  -- existed on 2026-09-12. mergeEntities moves identifiers today, so a non-zero
  -- count means some other path is soft-deleting without cleaning up.
  SELECT e.id AS entity_id, e.merged_into, i.kind, i.value
    FROM entities e
    JOIN entity_identifiers i ON i.entity_id = e.id AND i.status = 'active'
   WHERE e.workspace_id = ws AND e.status = 'merged'
),
member_id_is_not_a_urn AS (
  SELECT i.id, i.entity_id, i.value
    FROM entity_identifiers i
   WHERE i.workspace_id = ws AND i.status = 'active'
     AND i.kind = 'linkedin_member_id' AND i.value NOT LIKE 'ACoA%'
),
connection_not_syncing AS (
  SELECT c.id AS connection_id, p.name AS provider, c.owner_user_id, c.created_at, c.last_used_at
    FROM workflow_provider_connections c
    JOIN workflow_providers p ON p.id = c.provider_id
   WHERE c.workspace_id = ws AND c.is_verified AND c.managed_by = 'composio'
     AND c.composio_connection_id IS NOT NULL
     AND (   (p.name = 'google_calendar' AND c.created_at < now() - interval '6 hours'
              AND (c.last_used_at IS NULL OR c.last_used_at < now() - interval '6 hours'))
          OR (p.name = 'gmail_oauth' AND c.created_at < now() - interval '72 hours'
              AND (c.last_used_at IS NULL OR c.last_used_at < now() - interval '72 hours')))
)
SELECT 'person_without_identifier', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM person_without_identifier LIMIT 10) x), '[]'::jsonb),
       'Every active person can be matched by at least one identifier. Without one, the next mention of them forks a new record.'
  FROM person_without_identifier
UNION ALL
SELECT 'identifier_not_canonical', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM identifier_not_canonical LIMIT 10) x), '[]'::jsonb),
       'Every stored identifier is already in the shape a lookup will use. Matching is exact, so a non-canonical value is unreachable.'
  FROM identifier_not_canonical
UNION ALL
SELECT 'identifier_malformed_email', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM identifier_malformed_email LIMIT 10) x), '[]'::jsonb),
       'An email identifier is exactly one well-formed address. Two joined with a comma is two humans in one identifier, and matches neither.'
  FROM identifier_malformed_email
UNION ALL
SELECT 'company_domain_unreadable', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM company_domain_unreadable LIMIT 10) x), '[]'::jsonb),
       'A domain we can match on is also a domain we can read. The identifier serves resolution; the claim is what the UI and the agent see.'
  FROM company_domain_unreadable
UNION ALL
SELECT 'company_without_identifier', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM company_without_identifier LIMIT 10) x), '[]'::jsonb),
       'Every active company has a domain to key on. Without one it has no identifier at all, and every mention mints another copy.'
  FROM company_without_identifier
UNION ALL
SELECT 'duplicate_people_by_name', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM duplicate_people_by_name LIMIT 10) x), '[]'::jsonb),
       'Two active people rarely share a full name, and when they do it is usually one human split in two. Not a must-be-zero check — two real people can share a name — so watch the trend and review the pairs.'
  FROM duplicate_people_by_name
UNION ALL
SELECT 'claim_does_not_name_its_subject', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM claim_does_not_name_its_subject LIMIT 10) x), '[]'::jsonb),
       'An extracted fact names the person whose record it sits on. One that does not is describing somebody else.'
  FROM claim_does_not_name_its_subject
UNION ALL
SELECT 'unresolved_queue_actually_resolved', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM unresolved_queue_actually_resolved LIMIT 10) x), '[]'::jsonb),
       'Nothing sits in the unresolved queue that already landed on somebody. A queue that cries wolf is one the operator stops reading.'
  FROM unresolved_queue_actually_resolved
UNION ALL
SELECT 'system_note_rendered_as_intel', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM system_note_rendered_as_intel LIMIT 10) x), '[]'::jsonb),
       'The note.* namespace holds intelligence about a person, never the resolver talking to itself about its own plumbing.'
  FROM system_note_rendered_as_intel
UNION ALL
SELECT 'identifier_unreadable', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM identifier_unreadable LIMIT 10) x), '[]'::jsonb),
       'An identifier we can match on is also one we can read. The identifier serves resolution; the claim is what the UI and the agent see.'
  FROM identifier_unreadable
UNION ALL
SELECT 'merged_entity_still_resolvable', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM merged_entity_still_resolvable LIMIT 10) x), '[]'::jsonb),
       'A merged record resolves nothing. An identifier still active on one sends every lookup to a tombstone the views hide.'
  FROM merged_entity_still_resolvable
UNION ALL
SELECT 'member_id_is_not_a_urn', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM member_id_is_not_a_urn LIMIT 10) x), '[]'::jsonb),
       'linkedin_member_id holds member URNs. A vanity handle filed there is the same fact as a linkedin_url and will never match one.'
  FROM member_id_is_not_a_urn
UNION ALL
SELECT 'connection_not_syncing', count(*),
       coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM connection_not_syncing LIMIT 10) x), '[]'::jsonb),
       'A connected calendar or mailbox is actually delivering. "Verified" only means the OAuth worked once; a connection that reads nothing is a hole in every record it should be filling.'
  FROM connection_not_syncing;
$_$;


--
-- Name: FUNCTION run_invariants(ws uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.run_invariants(ws uuid) IS 'Data-quality invariants for one workspace. Each row is (name, violations, sample, description); zero violations is health. Deterministic SQL only — judgment belongs in the nightly reviewer, because a check that can be wrong is a check people learn to ignore.';


--
-- Name: search_claims(uuid, public.vector, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_claims(p_workspace_id uuid, p_embedding public.vector, p_threshold double precision, p_limit integer) RETURNS TABLE(id uuid, entity_id uuid, property text, value jsonb, confidence real, freshness text, similarity double precision)
    LANGUAGE plpgsql STABLE
    AS $$ 
  DECLARE v vector(1536) := p_embedding;   -- clean typed param → index-usable
  BEGIN
    RETURN QUERY
    SELECT t.id, t.entity_id, t.property, t.value, t.confidence, t.freshness, t.similarity
    FROM (
      SELECT c.id, c.entity_id, c.property, c.value, c.confidence, c.freshness,
             (1 - (c.embedding <=> v))::FLOAT AS similarity
      FROM claims c
      WHERE c.workspace_id = p_workspace_id AND c.embedding IS NOT NULL
      ORDER BY c.embedding <=> v
      LIMIT p_limit   
    ) t
    WHERE t.similarity >= p_threshold
    ORDER BY t.similarity DESC;
  END $$;


--
-- Name: search_claims(uuid, public.vector, double precision, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_claims(p_workspace_id uuid, p_embedding public.vector, p_threshold double precision, p_limit integer, p_property_prefix text DEFAULT NULL::text) RETURNS TABLE(id uuid, entity_id uuid, property text, value jsonb, confidence real, freshness text, valid_from timestamp with time zone, similarity double precision)
    LANGUAGE plpgsql STABLE
    AS $$
  DECLARE v vector(1536) := p_embedding;
  BEGIN
    IF p_property_prefix IS NULL THEN
      RETURN QUERY
      SELECT t.id, t.entity_id, t.property, t.value, t.confidence, t.freshness, t.valid_from, t.similarity
      FROM (
        SELECT c.id, c.entity_id, c.property, c.value, c.confidence, c.freshness, c.valid_from,
               (1 - (c.embedding <=> v))::FLOAT AS similarity
        FROM claims c
        WHERE c.workspace_id = p_workspace_id
          AND c.embedding IS NOT NULL
          AND c.invalid_at IS NULL
        ORDER BY c.embedding <=> v
        LIMIT p_limit
      ) t
      WHERE t.similarity >= p_threshold
      ORDER BY t.similarity DESC;
    ELSE
      RETURN QUERY
      WITH cand AS MATERIALIZED (
        SELECT c.id, c.entity_id, c.property, c.value, c.confidence, c.freshness, c.valid_from, c.embedding
        FROM claims c
        WHERE c.workspace_id = p_workspace_id
          AND c.embedding IS NOT NULL
          AND c.invalid_at IS NULL
          AND c.property LIKE p_property_prefix || '%'
      )
      SELECT t.id, t.entity_id, t.property, t.value, t.confidence, t.freshness, t.valid_from, t.similarity
      FROM (
        SELECT cand.id, cand.entity_id, cand.property, cand.value, cand.confidence, cand.freshness,
               cand.valid_from, (1 - (cand.embedding <=> v))::FLOAT AS similarity
        FROM cand
        ORDER BY cand.embedding <=> v
        LIMIT p_limit
      ) t
      WHERE t.similarity >= p_threshold
      ORDER BY t.similarity DESC;
    END IF;
  END $$;


--
-- Name: search_claims(uuid, public.vector, double precision, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_claims(p_workspace_id uuid, p_embedding public.vector, p_threshold double precision, p_limit integer, p_property_prefix text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, entity_id uuid, property text, value jsonb, confidence real, freshness text, valid_from timestamp with time zone, similarity double precision)
    LANGUAGE plpgsql STABLE
    AS $$
  DECLARE v vector(1536) := p_embedding;
  BEGIN
    IF p_entity_id IS NOT NULL THEN
      -- ONE ENTITY: its rows first, by btree; then the distance over that handful.
      RETURN QUERY
      WITH cand AS MATERIALIZED (
        SELECT c.id, c.entity_id, c.property, c.value, c.confidence, c.freshness, c.valid_from, c.embedding
        FROM claims c
        WHERE c.workspace_id = p_workspace_id
          AND c.entity_id = p_entity_id
          AND c.invalid_at IS NULL
          AND c.embedding IS NOT NULL
          AND (p_property_prefix IS NULL OR c.property LIKE p_property_prefix || '%')
      )
      SELECT t.id, t.entity_id, t.property, t.value, t.confidence, t.freshness, t.valid_from, t.similarity
      FROM (
        SELECT cand.id, cand.entity_id, cand.property, cand.value, cand.confidence, cand.freshness,
               cand.valid_from, (1 - (cand.embedding <=> v))::FLOAT AS similarity
        FROM cand
        ORDER BY cand.embedding <=> v
        LIMIT p_limit
      ) t
      WHERE t.similarity >= p_threshold
      ORDER BY t.similarity DESC;
    ELSIF p_property_prefix IS NULL THEN
      RETURN QUERY
      SELECT t.id, t.entity_id, t.property, t.value, t.confidence, t.freshness, t.valid_from, t.similarity
      FROM (
        SELECT c.id, c.entity_id, c.property, c.value, c.confidence, c.freshness, c.valid_from,
               (1 - (c.embedding <=> v))::FLOAT AS similarity
        FROM claims c
        WHERE c.workspace_id = p_workspace_id AND c.embedding IS NOT NULL AND c.invalid_at IS NULL
        ORDER BY c.embedding <=> v
        LIMIT p_limit
      ) t
      WHERE t.similarity >= p_threshold
      ORDER BY t.similarity DESC;
    ELSE
      RETURN QUERY
      WITH top AS MATERIALIZED (
        SELECT c.id, (1 - (c.embedding <=> v))::FLOAT AS similarity
        FROM claims c
        WHERE c.workspace_id = p_workspace_id
          AND c.embedding IS NOT NULL
          AND c.invalid_at IS NULL
          AND c.property LIKE p_property_prefix || '%'
        ORDER BY c.embedding <=> v
        LIMIT p_limit
      )
      SELECT c.id, c.entity_id, c.property, c.value, c.confidence, c.freshness, c.valid_from, top.similarity
      FROM top JOIN claims c ON c.id = top.id
      WHERE top.similarity >= p_threshold
      ORDER BY top.similarity DESC;
    END IF;
  END $$;


--
-- Name: search_document_chunks(uuid, public.vector, integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_document_chunks(p_workspace_id uuid, p_embedding public.vector, p_limit integer DEFAULT 20, p_threshold double precision DEFAULT 0.2) RETURNS TABLE(chunk_id uuid, document_id uuid, section_index integer, heading text, content text, similarity double precision)
    LANGUAGE sql STABLE
    AS $$
  select c.id, c.document_id, c.section_index, c.heading, c.content,
         1 - (c.embedding <=> p_embedding) as similarity
  from public.document_chunks c
  join public.documents d on d.id = c.document_id
  where c.workspace_id = p_workspace_id
    and d.status = 'live'
    and c.embedding is not null
    and 1 - (c.embedding <=> p_embedding) >= p_threshold
  order by c.embedding <=> p_embedding
  limit p_limit;
$$;


--
-- Name: search_document_chunks_fts(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_document_chunks_fts(p_workspace_id uuid, p_query text, p_limit integer DEFAULT 20) RETURNS TABLE(chunk_id uuid, document_id uuid, section_index integer, heading text, content text, rank real)
    LANGUAGE sql STABLE
    AS $$
  select c.id, c.document_id, c.section_index, c.heading, c.content,
         ts_rank(c.content_tsv, websearch_to_tsquery('english', p_query)) as rank
  from public.document_chunks c
  join public.documents d on d.id = c.document_id
  where c.workspace_id = p_workspace_id
    and d.status = 'live'
    and c.content_tsv @@ websearch_to_tsquery('english', p_query)
  order by rank desc
  limit p_limit;
$$;


--
-- Name: search_observations(uuid, public.vector, text, text, text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_observations(p_workspace_id uuid, p_embedding public.vector, p_kind text DEFAULT NULL::text, p_property_prefix text DEFAULT NULL::text, p_source text DEFAULT NULL::text, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, entity_id uuid, property text, value jsonb, source text, observed_at timestamp with time zone, similarity double precision)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE v vector(1536) := p_embedding;
BEGIN
  RETURN QUERY
  -- Re-rank a candidate pool (pulled fast by the vector index) so relevance is
  -- cosine × signal quality × recency, not cosine alone.
  SELECT c.id, c.entity_id, c.property, c.value, c.source, c.observed_at, c.similarity
  FROM (
    SELECT o.id, o.entity_id, o.property, o.value, o.source, o.observed_at,
           (1 - (o.embedding <=> v))::FLOAT AS similarity
    FROM observations o
    WHERE o.workspace_id = p_workspace_id
      AND o.embedding IS NOT NULL
      -- Only searchable meaning. Identity/stage/field rows never rank.
      AND (o.property LIKE 'note.%' OR o.property LIKE 'interaction.%')
      AND (p_kind            IS NULL OR o.kind = p_kind)
      AND (p_property_prefix IS NULL OR o.property ILIKE p_property_prefix || '%')
      AND (p_source          IS NULL OR o.source = p_source)
      AND (p_since           IS NULL OR o.observed_at >= p_since)
    ORDER BY o.embedding <=> v          -- vector index does the narrowing
    LIMIT GREATEST(p_limit * 5, 200)
  ) c
  ORDER BY
    c.similarity
    -- Signal weight, three tiers. Distilled facts and genuine two-way engagement
    -- carry full weight; one-way outbound touches half; operational/system events
    -- (added_to_campaign, enrichment_run, icp_scored, opens, signups) are near-zero
    -- so they never answer "who should I focus on".
    * CASE
        WHEN c.property LIKE 'note.%' THEN 1.0
        WHEN c.property IN (
          'interaction.email_replied', 'interaction.email_reply', 'interaction.positive_reply',
          'interaction.linkedin_reply', 'interaction.reply', 'interaction.email_received',
          'interaction.meeting_scheduled', 'interaction.meeting_held',
          'interaction.linkedin_connected', 'interaction.call_held', 'interaction.deal_won'
        ) THEN 1.0
        WHEN c.property IN (
          'interaction.linkedin_message', 'interaction.linkedin_post_engagement',
          'interaction.linkedin_engagement_comment', 'interaction.email_sent', 'interaction.proposal_sent'
        ) THEN 0.5
        ELSE 0.15
      END
    -- Recency: 90-day half-life, but never fully discounts an old-but-relevant hit.
    * (0.5 + 0.5 * exp(-EXTRACT(EPOCH FROM (now() - c.observed_at)) / (90 * 86400)))
    DESC
  LIMIT p_limit;
END $$;


--
-- Name: search_personal_files(uuid, uuid, public.vector, double precision, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_personal_files(p_workspace_id uuid, p_user_id uuid, p_embedding public.vector, p_threshold double precision DEFAULT 0.2, p_limit integer DEFAULT 8, p_folder text DEFAULT NULL::text) RETURNS TABLE(id uuid, folder text, subfolder text, name text, content text, similarity double precision)
    LANGUAGE plpgsql STABLE
    AS $$
  declare v vector(1536) := p_embedding;
  begin
    return query
    select t.id, t.folder, t.subfolder, t.name, t.content, t.similarity
    from (
      select f.id, f.folder, f.subfolder, f.name, f.content,
             (1 - (f.embedding <=> v))::float as similarity
      from public.personal_files f
      where f.workspace_id = p_workspace_id
        and f.user_id = p_user_id
        and f.embedding is not null
        and f.status <> 'inbox_pending'
        and (p_folder is null or f.folder = p_folder)
      order by f.embedding <=> v
      limit p_limit
    ) t
    where t.similarity >= p_threshold
    order by t.similarity desc;
  end $$;


--
-- Name: FUNCTION search_personal_files(p_workspace_id uuid, p_user_id uuid, p_embedding public.vector, p_threshold double precision, p_limit integer, p_folder text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_personal_files(p_workspace_id uuid, p_user_id uuid, p_embedding public.vector, p_threshold double precision, p_limit integer, p_folder text) IS 'Semantic search over one member''s private personal vault (Layer A). Scoped by (workspace_id, user_id); excludes unapproved inbox proposals.';


--
-- Name: set_contact_pipeline_stage(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_contact_pipeline_stage(p_contact_id uuid, p_stage text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    AS $$
  UPDATE contacts
  SET pipeline_stage            = p_stage,
      pipeline_stage_updated_at = now(),
      pipeline_stage_source     = 'manual'
  WHERE id = p_contact_id
    AND p_stage IN ('identified','aware','interested','evaluating','client');
$$;


--
-- Name: sync_subscription_plan_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_subscription_plan_name() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN NEW.plan_name := NEW.plan_id; NEW.updated_at := now(); RETURN NEW; END; $$;


--
-- Name: system_snapshot(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_snapshot(ws uuid, inbound_types text[]) RETURNS TABLE(metric text, value numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
WITH
inbound AS (
  SELECT o.id
    FROM observations o
   WHERE o.workspace_id = ws
     AND o.property = ANY (SELECT 'interaction.' || t FROM unnest(inbound_types) t)
     AND coalesce(o.raw->>'is_outbound', 'false') <> 'true'
     AND coalesce(o.value->>'summary', '') NOT LIKE 'You:%'
),
facts AS (
  SELECT c.value->'metadata'->>'source_activity_id' AS source_id
    FROM claims c
   WHERE c.workspace_id = ws
     AND c.property LIKE 'note.%' AND c.invalid_at IS NULL
     AND c.value->>'source' = 'signal_extraction'
),
cited AS (
  SELECT DISTINCT source_id FROM facts WHERE source_id IS NOT NULL
)
SELECT 'people.active', count(*)::numeric FROM entities
 WHERE workspace_id = ws AND type = 'person' AND status = 'active'
UNION ALL
SELECT 'companies.active', count(*)::numeric FROM entities
 WHERE workspace_id = ws AND type = 'company' AND status = 'active'
UNION ALL
SELECT 'extraction.inbound_sources', count(*)::numeric FROM inbound
UNION ALL
SELECT 'extraction.inbound_sources_with_claims', count(*)::numeric
  FROM inbound i JOIN cited c ON c.source_id = i.id::text
UNION ALL
SELECT 'extraction.facts_active', count(*)::numeric FROM facts
UNION ALL
SELECT 'identity.unresolved_pending', count(*)::numeric FROM unresolved_ingest
 WHERE workspace_id = ws AND status = 'pending'
$$;


--
-- Name: system_snapshot(uuid, text[], date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_snapshot(ws uuid, inbound_types text[], for_day date DEFAULT CURRENT_DATE) RETURNS TABLE(metric text, value numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
WITH
inbound AS (
  SELECT o.id
    FROM observations o
   WHERE o.workspace_id = ws
     AND o.property = ANY (SELECT 'interaction.' || t FROM unnest(inbound_types) t)
     AND coalesce(o.raw->>'is_outbound', 'false') <> 'true'
     AND coalesce(o.value->>'summary', '') NOT LIKE 'You:%'
),
facts AS (
  SELECT c.value->'metadata'->>'source_activity_id' AS source_id,
         c.value->>'category'                        AS category,
         c.value->'metadata'->>'quote'               AS quote,
         c.computed_at
    FROM claims c
   WHERE c.workspace_id = ws
     AND c.property LIKE 'note.%' AND c.invalid_at IS NULL
     AND c.value->>'source' = 'signal_extraction'
),
cited AS (
  SELECT DISTINCT source_id FROM facts WHERE source_id IS NOT NULL
),
-- What was asserted on the day being measured. A claim written before quotes shipped cannot have
-- one and must not drag the rate.
today AS (
  SELECT * FROM facts WHERE computed_at::date = for_day
)
SELECT 'people.active', count(*)::numeric FROM entities
 WHERE workspace_id = ws AND type = 'person' AND status = 'active'
UNION ALL
SELECT 'companies.active', count(*)::numeric FROM entities
 WHERE workspace_id = ws AND type = 'company' AND status = 'active'
UNION ALL
SELECT 'extraction.inbound_sources', count(*)::numeric FROM inbound
UNION ALL
SELECT 'extraction.inbound_sources_with_claims', count(*)::numeric
  FROM inbound i JOIN cited c ON c.source_id = i.id::text
UNION ALL
SELECT 'extraction.facts_active', count(*)::numeric FROM facts
UNION ALL
SELECT 'identity.unresolved_pending', count(*)::numeric FROM unresolved_ingest
 WHERE workspace_id = ws AND status = 'pending'
-- The distribution. One row per category actually present, the same shape llm.cost_usd.<model>
-- already uses, so a new category needs no migration to start being counted.
UNION ALL
SELECT 'noema.claims.' || coalesce(category, 'unknown'), count(*)::numeric
  FROM facts GROUP BY category
-- Honesty, as a flow.
UNION ALL
SELECT 'noema.claims_written', count(*)::numeric FROM today
UNION ALL
SELECT 'noema.claims_written_grounded', count(*)::numeric
  FROM today WHERE quote IS NOT NULL AND length(quote) > 3
$$;


--
-- Name: FUNCTION system_snapshot(ws uuid, inbound_types text[], for_day date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.system_snapshot(ws uuid, inbound_types text[], for_day date) IS 'The nightly per-workspace snapshot (GET-201), extended with Noema measures (GET-193): claim distribution by category, and the share of a day''s claims grounded in a checked quote.';


--
-- Name: team_active_accounts(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_active_accounts(ws_ids uuid[]) RETURNS bigint
    LANGUAGE sql STABLE
    AS $$
  WITH interacted AS (
    -- Every entity we have genuinely conversed with.
    SELECT DISTINCT o.entity_id
    FROM observations o
    WHERE o.workspace_id = ANY(ws_ids)
      AND o.kind = 'event'
      AND o.property = ANY(active_account_interaction_properties())
  ),
  live AS (
    -- Drop the merged, the archived, and our own team.
    SELECT i.entity_id, e.type
    FROM interacted i
    JOIN entities e ON e.id = i.entity_id
    WHERE e.status = 'active'
      AND NOT EXISTS (
        SELECT 1 FROM claims c
        WHERE c.entity_id = i.entity_id
          AND c.property = 'is_internal'
          AND c.value = 'true'::jsonb
          AND c.invalid_at IS NULL
      )
  ),
  accounts AS (
    -- A person rolls up to their company; a company counts directly; a person with
    -- no company is their own account. COALESCE collapses the first and third case.
    SELECT COALESCE(ct.company_id, l.entity_id) AS account_id
    FROM live l
    LEFT JOIN contacts ct ON ct.id = l.entity_id AND l.type = 'person'
  )
  SELECT COUNT(DISTINCT account_id) FROM accounts;
$$;


--
-- Name: team_agent_credit_cost(uuid[], timestamp with time zone, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_agent_credit_cost(ws_ids uuid[], p_since timestamp with time zone, p_features text[]) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  select coalesce(sum(cost_usd), 0)
  from public.llm_usage
  where workspace_id = any(ws_ids)
    and occurred_at >= p_since
    and feature = any(p_features);
$$;


--
-- Name: team_ops_breakdown(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_ops_breakdown(p_team_id uuid, p_since timestamp with time zone) RETURNS TABLE(event_type text, calls bigint, ops bigint)
    LANGUAGE sql STABLE
    AS $$
    SELECT wsl.event_type,
           COUNT(*)::bigint                          AS calls,
           COALESCE(SUM(wsl.billable_ops), 0)::bigint AS ops
    FROM workspace_system_log wsl
    JOIN workspaces w ON w.id = wsl.workspace_id
    WHERE w.team_id = p_team_id
      AND wsl.occurred_at >= p_since
    GROUP BY wsl.event_type;
  $$;


--
-- Name: team_ops_used(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_ops_used(p_team_id uuid, p_since timestamp with time zone) RETURNS bigint
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(SUM(wsl.billable_ops), 0)::bigint
  FROM workspace_system_log wsl
  JOIN workspaces w ON w.id = wsl.workspace_id
  WHERE w.team_id = p_team_id
    AND wsl.billable_ops > 0
    AND wsl.occurred_at >= p_since;
$$;


