--
-- Name: traverse_graph(uuid, uuid, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.traverse_graph(p_workspace_id uuid, p_start_entity uuid, p_max_depth integer DEFAULT 3, p_edge_types text[] DEFAULT NULL::text[]) RETURNS TABLE(depth integer, end_entity uuid, end_label text, path_entities uuid[], path_relationships text[])
    LANGUAGE sql STABLE
    AS $$
  with recursive walk as (
    -- Seed: depth 0, sitting on the start node.
    select
      0 as depth,
      p_start_entity as end_entity,
      null::text as end_label,
      array[p_start_entity] as path_entities,
      array[]::text[] as path_relationships
    union all
    select
      w.depth + 1,
      e.object_id,
      e.object_label,
      w.path_entities || e.object_id,
      w.path_relationships || e.relationship
    from walk w
    join public.workspace_graph_edges e
      on e.workspace_id = p_workspace_id
     and e.subject_id = w.end_entity
     and e.object_id is not null
     and (p_edge_types is null or e.relationship = any(p_edge_types))
    where w.depth < greatest(1, least(coalesce(p_max_depth, 3), 5))   -- clamp 1..5
      and not (e.object_id = any(w.path_entities))                    -- cycle guard
  )
  select depth, end_entity, end_label, path_entities, path_relationships
  from walk
  where depth > 0;
$$;


--
-- Name: trigger_recompute_pipeline_stage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_recompute_pipeline_stage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_new_stage  TEXT;
  v_cur_stage  TEXT;
  v_cur_source TEXT;
BEGIN
  IF NEW.activity_type IN ('airtable_imported','airtable_synced','airtable_pushed','contact_created') THEN
    RETURN NEW;
  END IF;

  IF NEW.occurred_at > now() THEN
    RETURN NEW;
  END IF;

  SELECT pipeline_stage, pipeline_stage_source
  INTO v_cur_stage, v_cur_source
  FROM contacts WHERE id = NEW.contact_id;

  IF v_cur_stage = 'client' THEN
    RETURN NEW;
  END IF;

  v_new_stage := compute_contact_pipeline_stage(NEW.contact_id);

  IF v_cur_source = 'auto'
     OR (v_cur_source = 'manual' AND v_new_stage = 'client')
     OR (v_cur_source = 'manual' AND (
           (v_new_stage = 'evaluating' AND v_cur_stage IN ('identified','aware','interested'))
        OR (v_new_stage = 'interested' AND v_cur_stage IN ('identified','aware'))
        OR (v_new_stage = 'aware'      AND v_cur_stage = 'identified')
     ))
  THEN
    UPDATE contacts SET
      pipeline_stage            = v_new_stage,
      pipeline_stage_updated_at = now(),
      pipeline_stage_source     = 'auto',
      last_activity_at          = GREATEST(COALESCE(last_activity_at, NEW.occurred_at), NEW.occurred_at)
    WHERE id = NEW.contact_id;
  ELSE
    UPDATE contacts SET
      last_activity_at = GREATEST(COALESCE(last_activity_at, NEW.occurred_at), NEW.occurred_at)
    WHERE id = NEW.contact_id;
  END IF;

  RETURN NEW;
END;
$$;


