--
-- Name: user_owns_template(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_owns_template(p_template_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$                                                                                                                                                                                                       
    SELECT EXISTS (                                                                                                                                                                                           
      SELECT 1 FROM templates t                                                                                                                                                                               
      INNER JOIN workspace_members wm ON wm.workspace_id = t.workspace_id                                                                                                                                     
      WHERE t.id = p_template_id                                                                                                                                                                              
      AND wm.user_id = auth.uid()                                                                                                                                                                             
    );                                                                                                                                                                                                        
  $$;


--
-- Name: visible_observations(uuid, uuid, uuid, boolean, text, text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.visible_observations(p_workspace_id uuid, p_entity_id uuid, p_viewer_user_id uuid, p_viewer_is_admin boolean, p_property text DEFAULT NULL::text, p_kind text DEFAULT NULL::text, p_as_of timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 200) RETURNS TABLE(id uuid, entity_id uuid, kind text, property text, value jsonb, source text, method text, source_confidence double precision, observed_at timestamp with time zone, ingested_at timestamp with time zone, owner_user_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.id, o.entity_id, o.kind, o.property, o.value, o.source, o.method,
         o.source_confidence, o.observed_at, o.ingested_at, o.owner_user_id
  from public.observations o
  where o.workspace_id = p_workspace_id
    and o.entity_id = p_entity_id
    and (p_property is null or o.property = p_property)
    and (p_kind is null or o.kind = p_kind)
    and (p_as_of is null or o.observed_at <= p_as_of)
    -- THE BACKSTOP — the exact rawVisible predicate, enforced here, not by the caller:
    --   admin sees all · a null-owner row is shared · otherwise only the viewer's own rows.
    and (p_viewer_is_admin or o.owner_user_id is null or o.owner_user_id = p_viewer_user_id)
  order by o.observed_at desc
  limit least(coalesce(p_limit, 200), 5000);
$$;


--
-- Name: visible_observations_v2(uuid, uuid, uuid, text[], boolean, text, text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.visible_observations_v2(p_workspace_id uuid, p_entity_id uuid, p_viewer_user_id uuid, p_viewer_emails text[], p_viewer_is_admin boolean, p_property text DEFAULT NULL::text, p_kind text DEFAULT NULL::text, p_as_of timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 200) RETURNS TABLE(id uuid, entity_id uuid, kind text, property text, value jsonb, source text, method text, source_confidence double precision, observed_at timestamp with time zone, ingested_at timestamp with time zone, owner_user_id uuid, external_id text, source_ref text, redacted boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with scoped as (
    select o.*,
           (o.property in (
              'interaction.email_sent', 'interaction.email_received', 'interaction.email_reply', 'interaction.email_replied',
              'interaction.linkedin_message', 'interaction.linkedin_message_sent', 'interaction.linkedin_message_received',
              'interaction.linkedin_replied', 'interaction.linkedin_reply',
              'interaction.linkedin_inmail', 'interaction.linkedin_inmail_sent', 'interaction.linkedin_inmail_received',
              'interaction.slack_dm', 'evidence.slack_dm_conversation'
            )) as is_message
    from public.observations o
    where o.workspace_id = p_workspace_id
      and o.entity_id = p_entity_id
      and (p_property is null or o.property = p_property)
      and (p_kind is null or o.kind = p_kind)
      and (p_as_of is null or o.observed_at <= p_as_of)
  ),
  judged as (
    select s.*,
           -- coalesce: any NULL in the chain (a legacy row without cc) must read as "not on it",
           -- never as an unknown that leaves `redacted` null.
           coalesce(not s.is_message
             or p_viewer_user_id is null
             or s.owner_user_id is null
             or s.owner_user_id = p_viewer_user_id
             or coalesce(s.raw -> 'mailbox_owner_ids', '[]'::jsonb) ? p_viewer_user_id::text
             or lower(coalesce(s.raw #>> '{participants,from}', s.raw ->> 'from', '')) = any(coalesce(p_viewer_emails, '{}'))
             or coalesce(s.raw #> '{participants,to}', '[]'::jsonb) ?| coalesce(p_viewer_emails, '{}')
             or coalesce(s.raw #> '{participants,cc}', '[]'::jsonb) ?| coalesce(p_viewer_emails, '{}')
             or (jsonb_typeof(s.raw -> 'to') = 'array' and (s.raw -> 'to') ?| coalesce(p_viewer_emails, '{}'))
             or (jsonb_typeof(s.raw -> 'cc') = 'array' and (s.raw -> 'cc') ?| coalesce(p_viewer_emails, '{}')),
           false) as content_ok
    from scoped s
  )
  select j.id, j.entity_id, j.kind, j.property,
         case when j.content_ok then j.value
              else jsonb_build_object(
                'description',
                case when j.property like 'interaction.email_%'
                     then 'Email ' || case when j.property like '%_sent' or (j.raw ->> 'is_outbound') = 'true' then 'sent' else 'received' end
                     when j.property in ('interaction.slack_dm', 'evidence.slack_dm_conversation')
                     then 'Slack message ' || case when (j.raw ->> 'is_outbound') = 'true' then 'sent' else 'received' end
                     else 'LinkedIn message ' || case when j.property like '%_sent' or (j.raw ->> 'is_outbound') = 'true' then 'sent' else 'received' end
                end,
                'summary', null)
         end as value,
         j.source, j.method, j.source_confidence, j.observed_at, j.ingested_at, j.owner_user_id,
         j.external_id, j.source_ref,
         not j.content_ok as redacted
  from judged j
  -- Which rows are returned at all: messages always (their content is judged above); anything
  -- else under the original rule — admin sees all, a member sees shared rows and their own.
  where j.is_message or p_viewer_is_admin or j.owner_user_id is null or j.owner_user_id = p_viewer_user_id
  order by j.observed_at desc
  limit least(coalesce(p_limit, 200), 5000);
$$;


--
-- Name: FUNCTION visible_observations_v2(p_workspace_id uuid, p_entity_id uuid, p_viewer_user_id uuid, p_viewer_emails text[], p_viewer_is_admin boolean, p_property text, p_kind text, p_as_of timestamp with time zone, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.visible_observations_v2(p_workspace_id uuid, p_entity_id uuid, p_viewer_user_id uuid, p_viewer_emails text[], p_viewer_is_admin boolean, p_property text, p_kind text, p_as_of timestamp with time zone, p_limit integer) IS 'Observations for one entity as a named viewer may see them. Message content (email / LinkedIn / Slack DM) is readable only by its participants and the members whose account holds a copy; everyone else gets the row with a label and redacted = true. Mirrors packages/core/src/privacy/messagePrivacy.mjs.';


--
-- Name: workspace_daily_ops(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workspace_daily_ops(p_workspace_id uuid, p_since timestamp with time zone) RETURNS TABLE(day date, cnt bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT occurred_at::date AS day, count(*)::bigint AS cnt
  FROM workspace_system_log
  WHERE workspace_id = p_workspace_id
    AND event_type IS DISTINCT FROM 'agent.chat'
    AND occurred_at >= p_since
  GROUP BY 1
$$;


--
-- Name: workspace_ops_stats(uuid, timestamp with time zone, text[], text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workspace_ops_stats(p_workspace_id uuid, p_since timestamp with time zone, p_retrieval text[], p_agent_sources text[], p_billed_only boolean DEFAULT false) RETURNS TABLE(all_time bigint, in_range bigint, failed bigint, agent bigint, system bigint)
    LANGUAGE sql STABLE
    AS $$
  WITH scoped AS (
    SELECT wsl.source, wsl.event_type, wsl.summary
    FROM workspace_system_log wsl
    WHERE wsl.workspace_id = p_workspace_id
      AND (p_since IS NULL OR wsl.occurred_at >= p_since)
      AND (NOT p_billed_only OR wsl.event_type = ANY(p_retrieval))
  )
  SELECT
    workspace_ops_used(p_workspace_id, '1970-01-01'::timestamptz)
      + (SELECT COUNT(*) FROM memory_ops_log m WHERE m.workspace_id = p_workspace_id),
    (SELECT COUNT(*) FROM scoped),
    (SELECT COUNT(*) FROM scoped s
       WHERE s.summary    ~* '(fail|error|denied|rejected|exception|invalid|unauthorized)'
          OR s.event_type ~* '(fail|error|denied|rejected|exception|invalid|unauthorized)'),
    (SELECT COUNT(*) FROM scoped s WHERE s.source = ANY(p_agent_sources)),
    (SELECT COUNT(*) FROM scoped s WHERE NOT (s.source = ANY(p_agent_sources)));
$$;


--
-- Name: workspace_ops_used(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workspace_ops_used(p_workspace_id uuid, p_since timestamp with time zone) RETURNS bigint
    LANGUAGE sql STABLE
    AS $$
  SELECT COALESCE(SUM(wsl.billable_ops), 0)::bigint
  FROM workspace_system_log wsl
  WHERE wsl.workspace_id = p_workspace_id
    AND wsl.billable_ops > 0
    AND wsl.occurred_at >= p_since;
$$;


