--
-- Name: agent_routines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_routines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    user_id uuid,
    name text NOT NULL,
    prompt text,
    enabled boolean DEFAULT true NOT NULL,
    trigger_kind text NOT NULL,
    frequency text,
    at_time time without time zone,
    day_of_week smallint,
    day_of_month smallint,
    timezone text DEFAULT 'UTC'::text NOT NULL,
    offset_minutes integer,
    last_run_at timestamp with time zone,
    next_run_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    entity_id uuid,
    condition jsonb,
    condition_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    action jsonb,
    artifact text,
    destination text DEFAULT 'none'::text NOT NULL,
    destination_target text,
    tools text[],
    steps jsonb,
    trigger_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    draft jsonb,
    edited_by uuid,
    CONSTRAINT agent_routines_artifact_check CHECK (((artifact IS NULL) OR (artifact = ANY (ARRAY['account_summary'::text, 'call_summary'::text, 'call_score'::text])))),
    CONSTRAINT agent_routines_day_of_month_check CHECK (((day_of_month >= 1) AND (day_of_month <= 28))),
    CONSTRAINT agent_routines_day_of_week_check CHECK (((day_of_week >= 0) AND (day_of_week <= 6))),
    CONSTRAINT agent_routines_destination_check CHECK ((destination = ANY (ARRAY['none'::text, 'email'::text, 'slack'::text, 'webhook'::text]))),
    CONSTRAINT agent_routines_frequency_check CHECK ((frequency = ANY (ARRAY['daily'::text, 'weekly'::text, 'monthly'::text, 'quarterly'::text]))),
    CONSTRAINT agent_routines_makes_something CHECK (((artifact IS NOT NULL) OR ((prompt IS NOT NULL) AND (length(btrim(prompt)) > 0)) OR ((steps IS NOT NULL) AND (jsonb_typeof(steps) = 'array'::text) AND (jsonb_array_length(steps) > 0)))),
    CONSTRAINT agent_routines_schedule_shape CHECK ((((trigger_kind = 'clock'::text) AND (frequency IS NOT NULL) AND (at_time IS NOT NULL) AND (offset_minutes IS NULL)) OR ((trigger_kind = 'before_meeting'::text) AND (offset_minutes IS NOT NULL) AND (frequency IS NULL)) OR ((trigger_kind <> ALL (ARRAY['clock'::text, 'before_meeting'::text])) AND (frequency IS NULL) AND (offset_minutes IS NULL)))),
    CONSTRAINT agent_routines_trigger_kind_check CHECK ((trigger_kind = ANY (ARRAY['call_ended'::text, 'before_meeting'::text, 'email_received'::text, 'reply_owed'::text, 'thread_quiet'::text, 'account_signal'::text, 'health_changed'::text, 'champion_quiet'::text, 'committee_joined'::text, 'icp_tier_changed'::text, 'expansion_signal'::text, 'promise_overdue'::text, 'posthog_event'::text, 'deal_stage_changed'::text, 'deal_closed_won'::text, 'deal_closed_lost'::text, 'deal_stalled'::text, 'deal_created'::text, 'hubspot_field_changed'::text, 'clock'::text, 'webhook_in'::text, 'manual'::text, 'call_scored'::text, 'condition'::text])))
);


