-- Name: insight_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.insight_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    source text DEFAULT 'external'::text NOT NULL,
    category text NOT NULL,
    statement text NOT NULL,
    quote text,
    speaker text,
    speaker_id uuid,
    occurred_at timestamp with time zone,
    status text DEFAULT 'new'::text NOT NULL,
    status_changed_at timestamp with time zone,
    status_changed_by uuid,
    dedup_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    theme_id uuid,
    lane text,
    subtype text,
    tag_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    contact_id uuid,
    company_id uuid,
    sorted_at timestamp with time zone,
    source_ref text,
    source_system text,
    kind text,
    CONSTRAINT insight_items_kind_check CHECK (((kind IS NULL) OR (kind = ANY (ARRAY['bug'::text, 'request'::text, 'improvement'::text, 'praise'::text])))),
    CONSTRAINT insight_items_lane_check CHECK (((lane IS NULL) OR (lane = ANY (ARRAY['product'::text, 'sales'::text, 'success'::text, 'market'::text])))),
    CONSTRAINT insight_items_source_check CHECK ((source = ANY (ARRAY['external'::text, 'team'::text]))),
    CONSTRAINT insight_items_subtype_check CHECK (((subtype IS NULL) OR (subtype = ANY (ARRAY['bug'::text, 'friction'::text, 'feature'::text, 'objection'::text, 'pricing'::text, 'pitch'::text, 'setup'::text, 'training'::text, 'partners'::text, 'buyers'::text]))))
);


