--
-- Name: TABLE system_metrics; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.system_metrics IS 'Daily snapshot per workspace, one row per metric per day (re-running a day overwrites it). These are LEVELS that cannot be recomputed for a past date later — claims get retired, people get merged — which is why they are stored rather than derived.';


--
-- Name: system_health_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.system_health_daily WITH (security_invoker='true') AS
 SELECT inv.day,
    inv.workspace_id,
    inv.metric,
    inv.kind,
    inv.value
   FROM ( SELECT DISTINCT ON (((invariant_checks.ran_at)::date), invariant_checks.workspace_id, invariant_checks.name) (invariant_checks.ran_at)::date AS day,
            invariant_checks.workspace_id,
            ('invariant.'::text || invariant_checks.name) AS metric,
            'level'::text AS kind,
            (invariant_checks.violations)::numeric AS value
           FROM public.invariant_checks
          ORDER BY ((invariant_checks.ran_at)::date), invariant_checks.workspace_id, invariant_checks.name, invariant_checks.ran_at DESC) inv
UNION ALL
 SELECT system_metrics.measured_on AS day,
    system_metrics.workspace_id,
    system_metrics.metric,
    'level'::text AS kind,
    system_metrics.value
   FROM public.system_metrics
UNION ALL
 SELECT (pipeline_events.occurred_at)::date AS day,
    pipeline_events.workspace_id,
    ('llm.'::text || pipeline_events.kind) AS metric,
    'flow'::text AS kind,
    (count(*))::numeric AS value
   FROM public.pipeline_events
  GROUP BY ((pipeline_events.occurred_at)::date), pipeline_events.workspace_id, pipeline_events.kind
UNION ALL
 SELECT (llm_usage.occurred_at)::date AS day,
    llm_usage.workspace_id,
    'llm.calls'::text AS metric,
    'flow'::text AS kind,
    (count(*))::numeric AS value
   FROM public.llm_usage
  GROUP BY ((llm_usage.occurred_at)::date), llm_usage.workspace_id
UNION ALL
 SELECT (llm_usage.occurred_at)::date AS day,
    llm_usage.workspace_id,
    'llm.cost_usd'::text AS metric,
    'flow'::text AS kind,
    round(sum(llm_usage.cost_usd), 4) AS value
   FROM public.llm_usage
  GROUP BY ((llm_usage.occurred_at)::date), llm_usage.workspace_id
UNION ALL
 SELECT (llm_usage.occurred_at)::date AS day,
    llm_usage.workspace_id,
    ('llm.cost_usd.'::text || llm_usage.model) AS metric,
    'flow'::text AS kind,
    round(sum(llm_usage.cost_usd), 4) AS value
   FROM public.llm_usage
  GROUP BY ((llm_usage.occurred_at)::date), llm_usage.workspace_id, llm_usage.model
UNION ALL
 SELECT (claims.computed_at)::date AS day,
    claims.workspace_id,
    'extraction.facts_written'::text AS metric,
    'flow'::text AS kind,
    (count(*))::numeric AS value
   FROM public.claims
  WHERE ((claims.property ~~ 'note.%'::text) AND ((claims.value ->> 'source'::text) = 'signal_extraction'::text))
  GROUP BY ((claims.computed_at)::date), claims.workspace_id;


--
-- Name: system_health_monthly; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.system_health_monthly WITH (security_invoker='true') AS
 SELECT (date_trunc('month'::text, (day)::timestamp with time zone))::date AS period,
    workspace_id,
    metric,
    kind,
        CASE
            WHEN (kind = 'flow'::text) THEN sum(value)
            ELSE (array_agg(value ORDER BY day DESC))[1]
        END AS value
   FROM public.system_health_daily
  GROUP BY ((date_trunc('month'::text, (day)::timestamp with time zone))::date), workspace_id, metric, kind;


--
-- Name: system_health_weekly; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.system_health_weekly WITH (security_invoker='true') AS
 SELECT (date_trunc('week'::text, (day)::timestamp with time zone))::date AS period,
    workspace_id,
    metric,
    kind,
        CASE
            WHEN (kind = 'flow'::text) THEN sum(value)
            ELSE (array_agg(value ORDER BY day DESC))[1]
        END AS value
   FROM public.system_health_daily
  GROUP BY ((date_trunc('week'::text, (day)::timestamp with time zone))::date), workspace_id, metric, kind;


--
-- Name: VIEW system_health_weekly; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.system_health_weekly IS 'The system, week by week. Example: select period, metric, value from system_health_weekly where workspace_id = ''<ws>'' and metric in (''extraction.inbound_sources'', ''extraction.inbound_sources_with_claims'', ''invariant.claim_does_not_name_its_subject'', ''llm.fallback'', ''llm.cost_usd'') order by period, metric;';


