COMMENT ON TABLE public.workspace_icp_model IS 'Per-workspace ICP scoring dials as YAML (base + personas + firmographics + signals + disqualifiers). Read by scoreDials; edited in Settings > ICP.';


--
-- Name: workspace_linkedin_connections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_linkedin_connections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    unipile_account_id text NOT NULL,
    linkedin_name text,
    linkedin_headline text,
    linkedin_profile_url text,
    connected_at timestamp with time zone DEFAULT now(),
    label text,
    owner_user_id uuid,
    is_active boolean DEFAULT true NOT NULL,
    engagement_enabled boolean DEFAULT true NOT NULL,
    last_engagement_scrape_at timestamp with time zone,
    engagement_scrape_requested_days integer,
    engagement_scrape_requested_at timestamp with time zone
);


--
-- Name: workspace_members; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_members (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role public.workspace_role NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    job_role text,
    agent_instructions text,
    notification_prefs jsonb,
    department_id uuid,
    onboarded_at timestamp with time zone,
    onboarding_reports jsonb,
    support_until timestamp with time zone,
    support_reason text,
    agent_name text,
    agent_prefs jsonb,
    agent_rules jsonb,
    job_roles text[],
    CONSTRAINT workspace_members_role_check CHECK ((role = ANY (ARRAY['owner'::public.workspace_role, 'admin'::public.workspace_role, 'member'::public.workspace_role, 'viewer'::public.workspace_role])))
);


--
-- Name: COLUMN workspace_members.job_role; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workspace_members.job_role IS 'The job this member does (founder, ae, sdr, revops, …). Read by the agent to personalize its answers. Distinct from `role`, which is the permission level.';


--
-- Name: COLUMN workspace_members.agent_instructions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workspace_members.agent_instructions IS 'Free-text instructions this member gives their agent. Injected into the agent system prompt for this member only.';


--
-- Name: COLUMN workspace_members.notification_prefs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workspace_members.notification_prefs IS 'Per-member notification preferences (daily digest + per-category email/app toggles). Shape owned by the frontend Settings → Notifications section; NULL = use defaults.';


--
-- Name: COLUMN workspace_members.onboarded_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workspace_members.onboarded_at IS 'When this seat finished their own welcome conversation. NULL = never onboarded; the router nudges them into it.';


--
-- Name: COLUMN workspace_members.support_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workspace_members.support_until IS 'Set only on operator support access. The row is deleted when it passes — see worker sweepSupportAccess.';


--
-- Name: workspace_own_domains; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_own_domains (
    workspace_id uuid NOT NULL,
    domain text NOT NULL,
    sources text[] DEFAULT '{}'::text[] NOT NULL,
    confirmed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE workspace_own_domains; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.workspace_own_domains IS 'Domains whose email addresses belong to this workspace''s own people (GET-291). One home for a fact four call sites used to guess at.';


--
-- Name: workspace_pipelines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_pipelines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    key text NOT NULL,
    label text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    owner_dept text DEFAULT 'sales'::text NOT NULL,
    entry_rule jsonb,
    is_terminal boolean DEFAULT false NOT NULL,
    source text DEFAULT 'default'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_pipelines_owner_dept_check CHECK ((owner_dept = ANY (ARRAY['sales'::text, 'customer_success'::text]))),
    CONSTRAINT workspace_pipelines_source_check CHECK ((source = ANY (ARRAY['default'::text, 'manual'::text])))
);


--
-- Name: TABLE workspace_pipelines; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.workspace_pipelines IS 'The revenue lifecycle phases a workspace defines for itself. Each owns a department, so entering one reassigns the account.';


--
-- Name: COLUMN workspace_pipelines.entry_rule; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workspace_pipelines.entry_rule IS 'derived | rule | manual. A rule PROPOSES via an unacknowledged lifecycle_event; it never advances an account itself.';


