);


--
-- Name: workspace_skills; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_skills (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid,
    name text NOT NULL,
    description text NOT NULL,
    body text NOT NULL,
    requires_providers text[] DEFAULT '{}'::text[] NOT NULL,
    allowed_tools text[] DEFAULT '{}'::text[] NOT NULL,
    est_cost_usd numeric(10,4),
    is_builtin boolean DEFAULT false NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    category text,
    summary text,
    visibility text DEFAULT 'private'::text NOT NULL,
    source text DEFAULT 'manual'::text NOT NULL,
    git_sha text,
    runtime text DEFAULT 'tool'::text NOT NULL,
    entrypoint text,
    required_secrets text[] DEFAULT '{}'::text[] NOT NULL,
    egress_hosts text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT workspace_skills_runtime_check CHECK ((runtime = ANY (ARRAY['tool'::text, 'sandbox'::text]))),
    CONSTRAINT workspace_skills_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'git'::text, 'plugin'::text]))),
    CONSTRAINT workspace_skills_visibility_check CHECK ((visibility = ANY (ARRAY['private'::text, 'workspace'::text])))
);


--
-- Name: COLUMN workspace_skills.runtime; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workspace_skills.runtime IS 'Which runtime executes this skill: tool (prose + fixed tools, the default) or sandbox (ephemeral container with the skill folder mounted — shell, files, scripts).';


--
-- Name: workspace_stages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_stages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    key text NOT NULL,
    label text NOT NULL,
    canonical text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    kind text DEFAULT 'active'::text NOT NULL,
    is_signup_default boolean DEFAULT false NOT NULL,
    source text DEFAULT 'manual'::text NOT NULL,
    external_ref text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pipeline text DEFAULT 'sales_pipeline'::text NOT NULL,
    pipeline_ref text,
    CONSTRAINT workspace_stages_canonical_check CHECK ((canonical = ANY (ARRAY['identified'::text, 'connected'::text, 'interested'::text, 'meeting_booked'::text, 'discovery'::text, 'demo'::text, 'negotiation'::text, 'closed_won'::text, 'closed_lost'::text, 'disqualified'::text, 'churned'::text]))),
    CONSTRAINT workspace_stages_kind_check CHECK ((kind = ANY (ARRAY['active'::text, 'won'::text, 'lost'::text, 'churned'::text])))
);


