    source text NOT NULL,
    event_type text NOT NULL,
    summary text NOT NULL,
    contact_id uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    billable_ops integer DEFAULT 1 NOT NULL,
    user_id uuid,
    use_case text
);


--
-- Name: COLUMN workspace_system_log.user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workspace_system_log.user_id IS 'The team member whose agent ran this op — from the API key''s owner (MCP/SDK) or the session (web). Null for workspace-scoped keys and for rows written before attribution existed.';


--
-- Name: COLUMN workspace_system_log.use_case; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.workspace_system_log.use_case IS 'The job this op served (meeting_prep, account_research, follow_up, …). Derived from the op for agent traffic, from the question for web chats. Null when it cannot be told.';


