--
-- Privileges. Supabase (and the shims) grant every new table, sequence and function to
-- anon, authenticated and service_role by default, and pg_dump only writes GRANTs, not
-- the REVOKEs migrations made since (entity_list_rows, visible_observations, ...). Start
-- those three roles from nothing so the GRANTs below are exactly what they end up with.
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated, service_role;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon, authenticated, service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM anon, authenticated, service_role;
--
-- Name: SCHEMA public; Type: ACL; Schema: -; Owner: -
--

GRANT USAGE ON SCHEMA public TO anon;
GRANT USAGE ON SCHEMA public TO authenticated;
GRANT USAGE ON SCHEMA public TO service_role;


--
-- Name: FUNCTION account_overview(p_workspace_id uuid, p_ids uuid[]); Type: ACL; Schema: public; Owner: -
--

REVOKE ALL ON FUNCTION public.account_overview(p_workspace_id uuid, p_ids uuid[]) FROM PUBLIC;
GRANT ALL ON FUNCTION public.account_overview(p_workspace_id uuid, p_ids uuid[]) TO service_role;


--
-- Name: FUNCTION account_signal_kind(prop text, old_v jsonb, new_v jsonb); Type: ACL; Schema: public; Owner: -
--

REVOKE ALL ON FUNCTION public.account_signal_kind(prop text, old_v jsonb, new_v jsonb) FROM PUBLIC;
GRANT ALL ON FUNCTION public.account_signal_kind(prop text, old_v jsonb, new_v jsonb) TO service_role;


--
-- Name: FUNCTION account_signals_from_claims(); Type: ACL; Schema: public; Owner: -
--

REVOKE ALL ON FUNCTION public.account_signals_from_claims() FROM PUBLIC;
GRANT ALL ON FUNCTION public.account_signals_from_claims() TO service_role;


--
-- Name: FUNCTION active_account_interaction_properties(); Type: ACL; Schema: public; Owner: -
--

REVOKE ALL ON FUNCTION public.active_account_interaction_properties() FROM PUBLIC;
